INSERT INTO _vm_library VALUES
  ('adjustable-wrench', 'tool', '9a0873af-8afb-4f78-9f23-15d7ad878989'::uuid, 'Adjustable Wrench', 'Adjustable wrench with a sliding jaw that fits hex nuts and fittings across a range of sizes, from supply stops to mounting hardware. Jaw capacity sets the largest nut each size can grip, and a snug jaw keeps the nut''s flats from rounding.', NULL, NULL),
  ('air-compressor', 'tool', 'd0594b9f-c266-4f6c-83e3-b0f088ec36ed'::uuid, 'Air Compressor', 'Portable oil-free air compressor that powers flooring nailers, finish nailers, and other pneumatic tools. The storage tank holds pressure between cycles, so fasteners drive to a consistent depth shot after shot.', NULL, NULL),
  ('angle-grinder', 'tool', '843f19eb-d33e-412c-ae4e-481ce93e66bd'::uuid, 'Angle Grinder', 'Handheld angle grinder that spins cutoff, grinding, diamond, and wire wheels at high speed to cut metal, grind concrete, and strip paint or rust. Disc size and power source change what it handles, from lock and bolt cuts to surface grinding.', NULL, NULL),
  ('bar-clamp', 'tool', 'e05ca10e-0833-4149-a94e-ab98eccf59e2'::uuid, 'Bar Clamp', 'Long-reach bar clamp with a sliding jaw and screw handle that applies even pressure across wide assemblies. The rigid bar resists bowing, so tabletops, bench tops, and panels close up flat and square.', NULL, NULL),
  ('belt-sander', 'tool', '96c73cdd-2c6c-4d1e-8398-bd2a51fab1eb'::uuid, 'Belt Sander', 'Handheld sander that drives a continuous abrasive belt over a flat platen for fast stock removal. It flattens glued panels and levels proud joints far faster than an orbital sander.', NULL, NULL),
  ('bucket', 'tool', '25022457-68a8-4421-89a7-5ff07e3035e7'::uuid, 'Bucket', 'Heavy-duty 5 gal bucket for mixing mortar, grout, and joint compound, and for hauling water and debris. Thick walls and a metal handle carry full, heavy loads without flexing.', NULL, NULL),
  ('caulk-gun', 'tool', 'dae5ad26-fe8c-49eb-b900-e4b7c5b7daa2'::uuid, 'Caulk Gun', 'Manual caulk gun that dispenses sealant and adhesive from standard cartridges in a steady, trigger-driven bead. Cartridge size sets the gun: 10 oz for standard caulk tubes, 29 oz for bulk adhesive and sealant.', NULL, NULL),
  ('chainsaw', 'tool', '0eea4485-6b9f-46e0-8132-0ab7f79890ac'::uuid, 'Chainsaw', 'Handheld saw that drives a toothed chain around a guide bar to cut through limbs, trunks, and firewood rounds. Bar length sets the largest cut, and gas or battery power sets runtime and weight.', NULL, NULL),
  ('chalk-line', 'tool', '5bf924dd-2af5-4066-96f1-ae25277acacc'::uuid, 'Chalk Line', 'Chalk line reel that snaps long, straight reference lines on floors, walls, decks, and roofs. The taut string leaves a sharp chalk line over any distance, well past where a straightedge runs out.', NULL, NULL),
  ('circular-saw', 'tool', 'a736b9f4-5c8f-43ca-b645-722ae41a9de3'::uuid, 'Circular Saw', '7-1/4 in circular saw for straight rip and crosscuts in lumber, plywood, and sheet goods. The standard blade size cuts through 2x framing in one pass and tilts for bevel cuts.', NULL, NULL),
  ('construction-adhesive', 'tool', 'd8f8edad-584f-443e-92de-8a705bb83429'::uuid, 'Construction Adhesive', 'Polyurethane construction adhesive in caulk-gun cartridges that bonds wood, concrete, masonry, stone, foam board, and metal for interior and exterior work. It cures waterproof and grips harder than ordinary adhesives, holding subfloor, stair treads, and landscape block that fasteners alone would let shift.', NULL, NULL),
  ('electrical-tape', 'tool', 'd811e4c1-f99d-48af-a9df-9611bfc589a1'::uuid, 'Electrical Tape', 'Vinyl electrical tape for insulating wire nut tails and marking conductors.', NULL, NULL),
  ('extension-cord', 'tool', 'a7a7ce49-73ed-4e78-a089-e6def91e8aa2'::uuid, 'Extension Cord', 'Heavy-duty 12-gauge extension cord rated for 15 A, built to run saws, mixers, and vacuums at full power. The heavy wire limits voltage drop over long runs, which protects motors from overheating.', NULL, NULL),
  ('fall-protection-harness', 'tool', '6d4e0d95-cbc3-45b8-80ec-3f61f5cfdb79'::uuid, 'Fall Protection Harness', 'Full-body harness for tying off on steep roof pitches during tear-off and nailing.', NULL, NULL),
  ('finish-nailer', 'tool', '513b72fa-33cf-4ef4-b18d-aceae3dfbab6'::uuid, 'Finish Nailer', 'Cordless 20V finish nailer family for trim, casing, baseboard, crown, and furniture. Nail gauge sets holding power and hole size: 15 and 16 gauge for thick profiles, 18 gauge and brad for lighter trim, and 23-gauge pin for near-invisible fastening.', NULL, NULL),
  ('foam-brush', 'tool', '2010b806-2500-4b06-9fa2-4ca7a8f2ccc3'::uuid, 'Foam Brush', 'Disposable foam brush for paints, stains, and clear coats on smooth surfaces. High-density foam lays a smooth finish without bristle marks. Pick width for detail edges vs broader panels.', NULL, NULL),
  ('grout-float', 'tool', '268b63a5-c35d-4350-9a5b-4cffab60a02e'::uuid, 'Grout Float', 'Rubber-faced grout float that packs grout into tile joints and strikes off the excess. The firm rubber face presses grout to full depth without scratching the tile surface.', NULL, NULL),
  ('heat-gun', 'tool', '94fb7cbe-329e-479b-80db-1bfc487add3f'::uuid, 'Heat Gun', 'Corded 120V heat gun with variable temperature for stripping paint, softening adhesives, shrinking film, and loosening stuck fasteners. Dial heat to match the material, then use the kickstand when you need both hands free.', NULL, NULL),
  ('hot-glue-gun', 'tool', 'c8fc6bfa-67e0-4544-87f4-b5945eca31d2'::uuid, 'Hot Glue Gun', 'Full-size dual-temperature hot melt glue gun for quick tacks on cardboard, craft foam, and thin wood templates. It heats in about a minute and lays a controllable bead, so scribing templates come together without waiting on clamps.', NULL, NULL),
  ('impact-driver', 'tool', 'a846b22d-a34c-4f2e-8fe4-f130800df0d0'::uuid, 'Impact Driver', 'Cordless impact driver that adds rotational hammer blows to drive long structural screws and lag hardware. The impacts keep the bit seated, preventing cam-out and wrist strain on long fasteners.', NULL, NULL),
  ('jigsaw', 'tool', 'af3567ce-0422-4360-a3f4-2c4245108b99'::uuid, 'Jigsaw', 'Orbital jigsaw for curved cuts, cutouts, and notches in wood, plywood, and sheet goods. The orbital action speeds rough cuts and switches off for clean, controlled detail work.', NULL, NULL),
  ('knee-pads', 'tool', '3a9c27a8-8691-4786-af2e-55ef2310ae9e'::uuid, 'Knee Pads', 'Basic foam knee pads for kneeling during floor work and low cuts.', NULL, NULL),
  ('ladder', 'tool', '45f556e5-ebd1-4125-94d3-c06b175120af'::uuid, 'Ladder', 'Fiberglass and aluminum ladders in step, extension, and multi-position styles for work at height. Rigid rails and wide-set feet keep the ladder steady while both hands are busy overhead.', NULL, NULL),
  ('leaf-blower', 'tool', '18bcc3eb-7b12-4a5f-afe0-d9247e8a4738'::uuid, 'Leaf Blower', 'Handheld blower that clears leaves, pine needles, grass clippings, and loose debris from lawns, driveways, walks, and decks. A high-velocity air stream herds debris into piles far faster than a rake or broom.', NULL, NULL),
  ('loppers', 'tool', '7b3a66fa-99ed-4f3d-923b-58d87b3c7920'::uuid, 'Loppers', 'Long-handled bypass pruners that cut branches too thick for hand pruners and too small for a saw. Curved bypass blades slide past each other like scissors, leaving a clean cut that heals well.', NULL, NULL),
  ('margin-trowel', 'tool', '6600a4c6-cf1e-40af-a552-1ad2232a8563'::uuid, 'Margin Trowel', 'Narrow, flat-ended trowel for scooping, mixing, and spreading mortar in tight spaces. The slim blade back-butters tile and reaches edges and corners that a notched trowel cannot.', NULL, NULL),
  ('miter-saw', 'tool', '91b01b72-4b9f-4415-b5b7-a912d4ba6d26'::uuid, 'Miter Saw', '12 in double-bevel compound miter saw that cuts square, mitered, and beveled ends on trim, lumber, and flooring. Bevels 0 to 48 degrees both ways and miters to 50, so crown and baseboard corners cut without flipping the stock.', NULL, NULL),
  ('moisture-meter', 'tool', '0a07c121-38c8-4a3e-bb82-633187115d33'::uuid, 'Moisture Meter', 'Moisture meter that reads the water content of wood subfloors, flooring, framing, and drywall before installation, in pin and pinless types. Pin meters read into the wood at the depth the probes reach, while pinless meters scan the surface without leaving holes.', NULL, NULL),
  ('multimeter', 'tool', 'f9518458-6831-4d9f-b0e3-84741f041b64'::uuid, 'Multimeter', 'Digital multimeter for checking voltage, continuity, and basic circuit diagnosis at outlets and switches.', NULL, NULL),
  ('paint-sprayer', 'tool', '02e141a8-eb50-407b-93f7-02787a392bc0'::uuid, 'Paint Sprayer', 'Airless paint sprayers that atomize unthinned coatings at high pressure for walls, ceilings, trim, and cabinets. Spraying lays an even film without roller stipple or brush marks and covers large areas far faster than rolling.', NULL, NULL),
  ('permanent-marker', 'tool', '51bce7f8-9ac4-41cf-aca0-e80441c877c6'::uuid, 'Permanent Marker', 'Permanent marker that writes clearly on tile backs, backer board, lumber, plastic, and metal. The ink stays legible through dust, water, and handling, so cut marks and labels last until the piece is installed.', NULL, NULL),
  ('pliers', 'tool', '3b8b1cba-507b-4b56-9c97-1105747337dc'::uuid, 'Pliers', 'Pliers for gripping, bending, twisting, and pulling hardware, wire, and fasteners. Jaw type sets the job: needle nose reaches into tight spaces, and linesman pliers twist and cut wire.', NULL, NULL),
  ('ppe-gloves', 'tool', '85cfc25d-3c4f-4f4e-8d76-72488743005b'::uuid, 'Work Gloves', 'Latex-coated work gloves with a breathable knit shell that protect hands from splinters, blisters, and scrapes while handling lumber, logs, tools, and debris. The textured latex palm holds a firm dry grip on rough material.', NULL, NULL),
  ('pressure-washer', 'tool', '07c36d08-3543-405c-b1d2-678876d6bafb'::uuid, 'Pressure Washer', 'Gas and electric pressure washers that lift dirt, mildew, and grime from siding, decks, driveways, and outdoor furniture. Pressure in psi and flow in GPM set how fast each option cleans, from light electric for furniture to heavy gas for large flatwork.', NULL, NULL),
  ('pry-bar', 'tool', '8b1430ee-34fe-403b-8879-683cddfa67ae'::uuid, 'Pry Bar', 'Flat steel pry bar for lifting tile, underlayment, baseboard, and trim during demolition. The thin, beveled end slides under material and the long handle multiplies leverage to pop it loose.', NULL, NULL),
  ('push-broom', 'tool', '5a54d6bb-d02f-48a0-9d3f-37fea3abd861'::uuid, 'Push Broom', 'Wide push broom that sweeps loose dirt, leaves, and grit off driveways, patios, and garage floors. Stiff outdoor bristles pull debris out of rough concrete texture instead of riding over it.', NULL, NULL),
  ('putty-knife', 'tool', '4175ef5d-092a-461a-a52c-97db01cb6704'::uuid, 'Putty Knife', 'Flexible steel putty knife for spreading filler and compound and scraping away paint, adhesive, and debris. Blade width sets coverage: narrow blades for nail holes and tight spots, wider blades for patches.', NULL, NULL),
  ('random-orbital-sander', 'tool', 'b8fcf2ac-a349-49d1-b1a4-cab8cfef96ef'::uuid, 'Random Orbital Sander', '5 in random orbital sander that spins and orbits its hook-and-loop pad at the same time. The random pattern leaves a smooth, swirl-free finish on wood, patched drywall, and painted trim.', NULL, NULL),
  ('receptacle-tester', 'tool', 'a26f19c6-4ece-4f19-b3f5-6d32cec9ead3'::uuid, 'Receptacle Tester', 'Three-light outlet tester that shows common wiring faults at duplex receptacles.', NULL, NULL),
  ('reciprocating-saw', 'tool', '3ee3d19d-46b3-4f62-8633-1f163aee6a9e'::uuid, 'Reciprocating Saw', 'Cordless reciprocating saw with a 1-1/8 in stroke and tool-free blade changes for demolition cuts through wood, nails, pipe, and drywall. The push-pull blade cuts in tight and awkward spots where a circular saw cannot fit.', NULL, NULL),
  ('rotary-hammer', 'tool', '122686f6-1d37-449c-b859-87e61fee0f15'::uuid, 'Rotary Hammer', 'Rotary hammer with drilling and chisel-only modes for boring into concrete and breaking up tile and mortar beds. Its piston-driven blow hits far harder than a standard hammer drill, breaking set mortar and masonry that a hand chisel barely marks.', NULL, NULL),
  ('router', 'tool', 'c9e004a0-2e9c-4c66-b445-3eb6b845dbbd'::uuid, 'Router', 'Power tool that spins a shaped cutting bit at high speed to profile edges, cut grooves, and trim flush. Fixed and plunge bases handle edge profiles, dados, and rabbets on furniture parts.', NULL, NULL),
  ('rubber-mallet', 'tool', 'a9168a0e-2d37-4f71-8e74-c894a2402350'::uuid, 'Rubber Mallet', 'Rubber mallet with a soft head that seats tile into mortar and taps flooring and parts into place without chipping or marking the surface. Head size sets the striking force.', NULL, NULL),
  ('safety-glasses', 'tool', '579eeb02-c184-493f-81e8-76537fcf4805'::uuid, 'Safety Glasses', 'Clear impact-rated safety glasses that shield eyes from chips, dust, and spray during cutting, grinding, splitting, and washing. Wraparound lenses block debris from the sides as well as the front.', NULL, NULL),
  ('shop-vac', 'tool', '7d666829-e7c0-48e8-8e55-121d9c9c82c2'::uuid, 'Shop Vac', 'Wet/dry shop vacuum that picks up dust, debris, water, and saw slurry from floors and work areas. Tank capacity sets how much it holds between emptying, from compact 6 gal units to 16 gal for large cleanups.', NULL, NULL),
  ('shovel', 'tool', '60393f71-2c35-4e1b-ad8b-f0a7eb16c2a8'::uuid, 'Digging Shovel', 'Full-length digging shovel with a D-handle grip for digging post holes and trenches, moving soil, and backfilling. Blade shape sets the options apart: a pointed tip breaks into hard or rooty ground, and a square edge cuts straight walls and flat hole bottoms.', NULL, NULL),
  ('speed-square', 'tool', 'f03517a7-d5c5-4bc7-95ea-3c1a2fe829b2'::uuid, 'Speed Square', 'Rafter square for marking and checking 90 and 45 degree angles and guiding straight saw cuts. The fence hooks over the edge of a board for fast, repeatable layout marks.', NULL, NULL),
  ('table-saw', 'tool', '4752c4e2-3812-48ae-9e30-0a4eafc80ac9'::uuid, 'Table Saw', 'Portable 10 in table saw for repeatable rips, crosscuts, and sizing of boards and sheet goods on a stable surface. A fence locked parallel to the blade repeats the same width cut after cut, so matched parts and long rips come out straight.', NULL, NULL),
  ('tape-measure', 'tool', 'ff8e2e15-be5d-4a56-a615-10b6b122440f'::uuid, 'Tape Measure', 'Tape measure for measuring rooms, cut lengths, layout lines, and long outdoor runs. Length sets the options apart: the 25 ft locking tape covers rooms and cut marks, and the 100 ft long tape reaches across yards, fence lines, and foundations in one pull.', NULL, NULL),
  ('tile-leveling-clips', 'material', '2bce9e54-8276-4ed5-b92f-cb80845263c0'::uuid, 'Tile Leveling Clip', 'Flat-base leveling clips with threaded posts that hold tile edges flush while thinset cures. The base doubles as a spacer that sets grout joint width, and the post snaps off below the surface once the mortar sets.', NULL, NULL),
  ('track-saw', 'tool', 'cffb24a7-9485-4992-ae20-e0c4eb4de95f'::uuid, 'Track Saw', 'Plunge-cut circular saw that rides on an aluminum guide rail for straight, splinter-free cuts. It rips and crosscuts full sheets of plywood and MDF with table-saw accuracy on site.', NULL, NULL),
  ('utility-knife', 'tool', '920679a3-1887-482c-8867-5b45ddec02a2'::uuid, 'Utility Knife', 'Retractable utility knife with replaceable blades for scoring backer board and cutting membrane, drywall, carpet, and packaging. The blade locks at set depths and retracts between cuts.', NULL, NULL),
  ('water-hose', 'tool', 'a3540506-a781-4216-ace2-a497f6342456'::uuid, 'Water Hose', 'Garden hose with standard 3/4 in fittings for supplying water to wet saws, pressure washers, and cleanup stations. Length sets the reach from the nearest spigot.', NULL, NULL),
  ('wax-ring', 'material', '92f4f2b9-8f32-4840-9565-f8bcf6c51c96'::uuid, 'Wax Ring', 'Molded wax gasket with a built-in horn that seals the toilet to the closet flange. The seal is single-use, so each toilet reset after new flooring needs a fresh ring.', NULL, NULL),
  ('wheelbarrow', 'tool', '6027e726-2e82-4891-b473-7d112d49f522'::uuid, 'Wheelbarrow', 'Poly wheelbarrow for hauling split firewood, chips, soil, and tools around the yard. A pneumatic front tire and sturdy handles balance a full load on uneven ground.', NULL, NULL),
  ('wire-brush', 'tool', 'ae914bcd-c5a2-444a-a346-35a014bcbefc'::uuid, 'Wire Brush', 'Hand wire brush with stiff steel bristles for scrubbing rust, scale, flaking paint, and stuck grime off metal and masonry. Carbon steel bristles cut hardest on rust and iron, while stainless bristles leave no rusting steel behind on masonry, aluminum, or stainless.', NULL, NULL),
  ('wood-filler', 'tool', 'b0ad9aab-f167-4310-a21b-d10e05e7b318'::uuid, 'Wood Filler', 'Wood filler in interior stainable and exterior formulas that packs into nail holes, gouges, and cracks in trim, doors, and siding. It dries hard and sands flush so paint or stain hides the repair, and the exterior formula holds up outdoors under a paint coat.', NULL, NULL),
  ('alkali-resistant-seam-tape', 'material', 'a3be3ed2-7ff1-44c4-b433-58995470735f'::uuid, 'Alkali-Resistant Seam Tape', 'Alkali-resistant fiberglass mesh tape for reinforcing cement board joints and uncoupling membrane seams under tile. The coating holds up to the high alkalinity of thinset, which breaks down standard drywall mesh over time.', NULL, NULL),
  ('carpenter-pencils', 'tool', 'c27568eb-96d3-4ce2-863a-7ad2f11777e4'::uuid, 'Carpenter Pencil', 'Flat carpenter pencil with a thick lead that marks clearly on wood, drywall, tile backs, and rough surfaces. The flat body keeps it from rolling off ladders and sloped work.', NULL, NULL),
  ('contractor-trash-bags', 'material', '1b414da8-9759-4839-8b1e-ac992428dd9c'::uuid, 'Contractor Trash Bag', 'Heavy-duty contractor bag, thicker than kitchen bags, for tear-out debris, broken tile, drywall scraps, and packaging. Resists punctures from the sharp edges and nails that split standard trash bags.', NULL, NULL),
  ('floor-tile', 'material', '5212776d-6cee-4f79-8ee5-09f545188d06'::uuid, 'Floor Tile', 'Field tile for the main floor area, in ceramic, porcelain, or stone. Tile choice sets the layout, grout joint width, and trowel notch for the rest of the install.', NULL, NULL),
  ('leaf-rake', 'tool', '7b6fa535-bee0-44d3-af5c-c8262de351f7'::uuid, 'Leaf Rake', 'Wide fan rake with flexible tines that gather leaves without tearing up turf. The broad head clears edges, beds, and wet mats that a blower leaves behind.', NULL, NULL),
  ('plastic-sheeting', 'material', '54d8ba92-e6bf-43bc-bee8-7643e3f5be4a'::uuid, 'Plastic Sheeting', 'Thin plastic sheeting in wide rolls for masking floors, furniture, and doorways. The lightweight film drapes over large areas, catching drips, overspray, and sanding dust.', NULL, NULL),
  ('uncoupling-membrane', 'material', 'ecc409ba-6240-4a17-bdef-7f67afbb6d95'::uuid, 'Uncoupling Membrane', 'Plastic uncoupling membrane with a fleece backing that bonds between the subfloor and tile. Its dimpled cavities let the subfloor shift slightly without cracking the tile or grout above.', NULL, NULL),
  ('wood-glue', 'material', 'd3b50e21-61fc-4a87-9a2f-7ae6ea4ef003'::uuid, 'Wood Glue', 'Water-resistant PVA wood glue for furniture glue-ups, edge joints, and trim miters. Once clamped and cured, the bond is stronger than the wood fibers around it.', NULL, NULL),
  ('framing-nailer', 'tool', '369c5a61-9a21-4cca-bb21-471521eaeb60'::uuid, 'Framing Nailer', 'Cordless framing nailer that drives full-size framing nails into dimension lumber without a hose or compressor. It speeds up partition walls, closet framing, and other non-structural build-outs.', NULL, NULL),
  ('level', 'tool', '11abddd4-0fba-455e-ae6e-42efec824deb'::uuid, 'Level', 'Spirit level with bubble vials for checking level, plumb, and flat on floors, walls, and framing. Length sets the span it reads: short levels fit tight spots, and long levels bridge dips and humps across wide areas.', NULL, NULL),
  ('nitrile-gloves', 'material', 'c31bff60-f0a7-4bad-8a00-ead94d112ca2'::uuid, 'Nitrile Gloves', 'Disposable nitrile gloves that protect hands from paint, stain, thinset, grout, and light chemicals. Nitrile resists solvents and punctures better than latex and avoids latex allergies.', NULL, NULL),
  ('notched-trowel', 'tool', '82c7ff52-df8c-43c7-9ac6-eac0d37c0502'::uuid, 'Notched Trowel', 'Square- and V-notch trowels that spread thinset in even ridges of a set height. Notch size controls how much mortar sits under the tile, from thin layers for mosaics to deep beds for large-format tile.', NULL, NULL),
  ('oscillating-multi-tool', 'tool', 'e01ea34e-9229-44fd-83e8-62ece12e6d6e'::uuid, 'Oscillating Multi-Tool', 'Oscillating multi-tool that drives cutting, scraping, and sanding blades in fast side-to-side strokes. Makes flush cuts, plunge cuts, and grout removal in tight spots that saws cannot reach.', NULL, NULL),
  ('painters-tape', 'material', '29a219d3-1ba4-4329-b3c7-514dd5462a7a'::uuid, 'Painters Tape', 'Painter''s masking tape in 1, 1.5, and 2 in widths that protects trim, glass, and finished surfaces. Medium adhesion holds a sharp edge and releases without pulling paint or leaving residue.', NULL, NULL),
  ('power-drill', 'tool', '008edd1b-d61a-4b6c-b50c-a5125ac3b92e'::uuid, 'Power Drill', 'Power drill that bores holes and drives screws in wood, metal, and backer board. An adjustable clutch stops the screw at a set torque, so heads seat flush without stripping or overdriving.', NULL, NULL),
  ('tile-saw', 'tool', 'fc76778e-8170-4ea3-a6f2-5c4a2c090685'::uuid, 'Wet Tile Saw', 'Wet tile saw with a diamond blade and water cooling for straight and miter cuts in ceramic, porcelain, and stone. Water keeps the blade cool and holds dust down, leaving clean, chip-free edges.', NULL, NULL),
  ('sponge', 'tool', '0b1b75d8-63e3-423c-a7b8-a2d6ecfb9d5e'::uuid, 'Sponge', NULL, NULL, NULL),
  ('spackle', 'material', 'd3b50e21-61fc-4a87-9a2f-7ae6ea4ef002'::uuid, 'Spackle', NULL, NULL, NULL),
  ('allen-key-set', 'tool', 'b2549538-1b64-402c-8a72-cfb51739680a'::uuid, 'Allen Key Set', NULL, NULL, NULL),
  ('awl', 'tool', '5763c163-defe-48fa-b0d7-f0a2469ffb0b'::uuid, 'Awl', NULL, NULL, NULL),
  ('backer-board-scoring-knife', 'tool', 'a0eb415b-c4b1-4263-b076-f45a60eec747'::uuid, 'Backer Board Scoring Knife', NULL, NULL, NULL),
  ('band-saw', 'tool', 'c3b7fd44-3f9e-445d-b184-fa8a3e2c7a97'::uuid, 'Band Saw', NULL, NULL, NULL),
  ('beating-block', 'tool', '3a4c2ffd-e97a-4ee9-ab7d-0d1264167060'::uuid, 'Beating Block', NULL, NULL, NULL),
  ('brad-nailer', 'tool', '35a4552b-c2b1-4edb-a1b9-7eb48b9cbf6d'::uuid, 'Brad Nailer', NULL, NULL, NULL),
  ('carbide-tile-cutter', 'tool', '8edd8e3f-7be9-41cb-a4f0-4d40df03a78d'::uuid, 'Carbide Tile Cutter', NULL, NULL, NULL),
  ('caulking-finishing-tool', 'tool', '92b2ecee-628f-4705-80ac-705e34463026'::uuid, 'Caulking Finishing Tool', NULL, NULL, NULL),
  ('chemical-resistant-gloves', 'tool', 'ba1c042e-f12b-442e-a473-5553306bfaac'::uuid, 'Chemical-Resistant Gloves', NULL, NULL, NULL),
  ('clamp-set', 'tool', '8302a8d5-f719-48d8-a1cb-165b3f1cec1c'::uuid, 'Clamp Set', NULL, NULL, NULL),
