  ('angle-grinder-wheel', 'material', NULL, 'Angle Grinder Wheel', 'Interchangeable wheels, discs, and pads that fit standard angle grinder arbors. Each type does a different job: cutoff wheels slice metal, diamond wheels cut tile and grind concrete, and wire, flap, and stripping wheels clean and smooth surfaces.', 'Consumables', NULL),
  ('appliance-dolly', 'tool', NULL, 'Appliance Dolly', 'Strap-equipped hand truck for moving refrigerators, ranges, and dishwashers out of tight bays and across finished floors. A strap holds the appliance to the frame, and weight capacity sets the heaviest load each size carries.', 'Other', 2),
  ('automated-paint-roller', 'tool', NULL, 'Automated Paint Roller', 'Motorized paint roller that pumps paint from a built-in reservoir or directly from the can to the roller cover. The steady feed keeps a wet edge across long walls and ceilings, avoiding the lap marks that come from stopping to reload a tray.', 'Power Tool', 3),
  ('bolt-cutter', 'tool', NULL, 'Bolt Cutter', 'Compound-leverage bolt cutter with hardened jaws for cutting bolts, padlocks, chain, and heavy wire. The compound linkage multiplies hand force, so the long handles shear hardened steel that snips cannot.', 'Hand Tool', 2),
  ('broom-dustpan', 'tool', NULL, 'Broom and Dustpan', 'Upright broom and dustpan set for sweeping dust, grit, and debris from floors between work stages. A clean floor keeps grit out of fresh finishes and from scratching surfaces underfoot.', 'Other', 1),
  ('bucket-liner', 'material', NULL, 'Bucket Liner', 'Disposable plastic liner for standard 5 gal buckets that catches mortar, grout, and paint. Cured material lifts out with the liner instead of hardening onto the bucket walls.', 'Consumables', NULL),
  ('bucket-scoop', 'tool', NULL, 'Bucket Scoop', 'Stainless steel scoop curved to match the inside of a standard 5 gal bucket. Scrapes the sides and bottom clean, so mortar and grout come out without waste.', 'Hand Tool', 2),
  ('cabinet-door-drying-rack', 'tool', NULL, 'Cabinet Door Drying Rack', 'Stand that holds cabinet doors and drawers upright while finish coats dry.', 'Other', 3),
  ('cabinet-hardware-jig', 'tool', NULL, 'Cabinet Hardware Jig', 'Adjustable mounting template for drilling knobs and pulls on cabinet doors and drawers. Hardened drill guides and an end stop keep hole spacing and edge distance consistent across every door.', 'Hand Tool', 3),
  ('canvas-drop-cloth', 'tool', NULL, 'Canvas Drop Cloth', 'Heavy canvas drop cloth, from 4 x 8 ft runners to 12 x 15 ft room covers, that protects floors and furniture from paint, dust, and debris. Woven canvas absorbs drips and stays flat underfoot, where plastic sheeting slides and lets paint pool.', 'Other', 1),
  ('carpet-fan', 'tool', NULL, 'Carpet Fan', 'Air mover that blows a high-velocity stream of air across carpet, pad, floors, and walls to speed drying. Moving air low across a wet surface pulls moisture out faster than room air alone, cutting dry times after cleaning, leaks, or fresh coatings.', 'Power Tool', 3),
  ('carpet-power-stretcher', 'tool', NULL, 'Carpet Power Stretcher', 'Power stretcher that pulls carpet tight across the room so seams stay flat and wrinkles stay out.', 'Hand Tool', 3),
  ('carpet-seaming-iron', 'tool', NULL, 'Carpet Seaming Iron', 'Electric seaming iron that activates seam tape so carpet widths join flat and strong.', 'Power Tool', 3),
  ('caulk-removal-tool', 'tool', NULL, 'Caulk Removal Tool', 'Hand tool with angled scraper and hook edges that cut cured caulk loose and pull it out of joints. Clears old silicone and latex from tub, tile, and trim seams so new sealant bonds to a clean surface.', 'Hand Tool', 2),
  ('caution-tape', 'material', NULL, 'Caution Tape', 'High-visibility barricade tape that marks off work zones, wet floors, and hazards. Bright printed tape strung across doorways and walkways keeps people out of fresh finishes and cutting areas.', 'Consumables', NULL),
  ('cleaning-toothbrush', 'tool', NULL, 'Cleaning Toothbrush', 'Stiff-bristle detail brush for scrubbing grout lines, corners, and textured tile. The small head reaches tight joints and edges that a sponge or full-size brush cannot.', 'Other', 1),
  ('combination-square', 'tool', NULL, 'Combination Square', 'Layout square with a sliding head, etched blade, and built-in level vial for marking square lines, checking door edges, and transferring hinge and hardware heights.', 'Hand Tool', 2),
  ('come-along', 'tool', NULL, 'Come Along', 'Hand winch for tensioning fabric, pulling posts plumb, and temporary holds.', 'Hand Tool', 3),
  ('compass-scribe', 'tool', NULL, 'Compass Scribe', 'Scribing compass that traces an irregular wall, floor, or cabinet edge onto the piece being fitted. One leg follows the contour while the pencil leg transfers it, so tile, trim, and panels fit tight to uneven surfaces.', 'Hand Tool', 3),
  ('concealed-hinge-jig', 'tool', NULL, 'Concealed Hinge Jig', 'Adjustable jig for boring 35 mm cup holes for European-style concealed cabinet hinges with a hand drill. Indexing cams set hinge offset, and the included carbide bit with stop collar keeps cup depth consistent door to door.', 'Hand Tool', 3),
  ('contour-gauge', 'tool', NULL, 'Contour Gauge', 'Profile gauge with sliding pins that copy the exact shape of door casings, pipes, and irregular edges. The locked profile transfers straight onto tile or trim for clean, close-fitting cutouts.', 'Hand Tool', 2),
  ('deburring-tool', 'tool', NULL, 'Deburring Tool', 'Hand deburrer with a swiveling blade that cleans the inside and outside edge of cut pipe. Removing burrs and chamfering the end lets primer and cement wet the full joint and keeps the pipe from scraping cement out of the fitting.', 'Hand Tool', 2),
  ('dewalt-60v-20v-charger', 'tool', NULL, 'Battery Charger', 'Dual-voltage charger that recharges 60V and 20V lithium-ion tool batteries from a standard grounded outlet. A status light shows when each pack is full, so a spare can charge while another one runs.', 'Other', 1),
  ('dewalt-battery', 'tool', NULL, 'Tool Battery', 'Rechargeable lithium-ion battery packs for cordless tools, in 20V packs for handheld tools and 60V packs for high-draw outdoor equipment. Capacity in amp-hours sets how long each pack runs between charges.', 'Other', 1),
  ('diamond-drilling-kit', 'tool', NULL, 'Diamond Core Bit Set', 'Diamond core bits for drilling clean round holes through porcelain, ceramic tile, and stone. The diamond-embedded rim grinds rather than chips, leaving smooth edges for valves, pipes, and fixtures.', 'Other', 3),
  ('diamond-hole-saw-kit', 'tool', NULL, 'Diamond Hole Saw Kit', 'Diamond core bit kit with multiple diameters, a centering guide, and a water feed for drilling clean holes in tile, porcelain, and stone. Diamond grit grinds through dense tile that shatters or dulls standard hole saws, and water keeps the bit cool.', 'Other', 3),
  ('diamond-polishing-blocks', 'tool', NULL, 'Diamond Polishing Blocks', 'Hand-held diamond abrasive blocks for smoothing and polishing cut tile and stone edges. Graded grits remove saw chips and sharp corners, leaving exposed edges smooth and safe to touch.', 'Hand Tool', 3),
  ('digging-bar', 'tool', NULL, 'Digging Bar', 'Heavy steel bar for breaking hardpan, prying rocks, and widening post holes.', 'Hand Tool', 2),
  ('digital-angle-finder', 'tool', NULL, 'Angle Finder', 'Digital angle finder that measures inside and outside corners and displays the miter and bevel angles to cut. Reads corners that are not a true 90 degrees, so trim and tile meet tight without trial cuts.', 'Hand Tool', 2),
  ('do-not-walk-sign', 'tool', NULL, 'Do Not Walk Sign', 'Floor sign to keep traffic off fresh tile or grout.', 'Other', 2),
  ('drum-floor-sander', 'tool', NULL, 'Drum Floor Sander', 'Rental-class drum sander with dust-control port for aggressive flattening of hardwood floors.', 'Power Tool', 3),
  ('drywall-mud-pan', 'tool', NULL, 'Drywall Mud Pan', 'Stainless steel mud pan that holds joint compound within reach while taping and patching. Straight, sharp edges scrape the knife clean on every pass, keeping dried bits and excess mud off the wall.', 'Hand Tool', 2),
  ('drywall-pole-sander', 'tool', NULL, 'Drywall Pole Sander', 'Telescoping pole sander with a swivel head that holds sanding screens flat against walls and ceilings. The pivoting head keeps even pressure across wide seams, so joint compound sands smooth without gouges or ladder moves.', 'Hand Tool', 2),
  ('drywall-stilts', 'tool', NULL, 'Drywall Stilts', 'Adjustable plasterer stilts that raise the wearer to ceiling height for taping, mudding, and sanding. Spring-loaded ankle joints flex with each step, so work moves along a wall without climbing down to reposition a ladder.', 'Other', 3),
  ('drywall-taping-knife', 'tool', NULL, 'Drywall Taping Knife', 'Stainless steel taping knife with a flexible blade for spreading and feathering joint compound. Wider blades spread compound thinner across seams and patches, leaving a flat finish that needs less sanding.', 'Hand Tool', 2),
  ('electric-space-heater', 'tool', NULL, 'Electric Space Heater', 'Pivoting ceramic utility heater for garages, basements, and indoor work areas. Plug into a standard 120V outlet (no extension cords). Tip the head to aim warmth where you are working.', 'Other', 2),
  ('fence-stretcher', 'tool', NULL, 'Fence Stretcher', 'Pull chain-link fabric tight before tying it off to posts and rails.', 'Hand Tool', 3),
  ('fiber-cement-shear', 'tool', NULL, 'Fiber Cement Shear', 'Pneumatic or electric shear for dust-controlled cuts in fiber cement siding and trim boards.', 'Power Tool', 3),
  ('finishing-trowel', 'tool', NULL, 'Finishing Trowel', '12 x 4 in high-carbon steel finishing trowel with a curved wood handle for mortar beds, concrete, and plaster. The flat, tempered blade compacts the surface and closes pores for a dense, smooth finish after floating.', 'Hand Tool', 2),
  ('floor-buffer', 'tool', NULL, 'Floor Buffer', 'Orbital floor buffer for screening between coats and light recoat prep without full drum sanding.', 'Power Tool', 3),
  ('floor-edger', 'tool', NULL, 'Floor Edger', 'Disc edger for sanding along walls, corners, and closets where a drum sander cannot reach.', 'Power Tool', 3),
  ('floor-roller', 'tool', NULL, 'Floor Roller', '100 lb class vinyl and linoleum roller for seating glue-down planks evenly.', 'Hand Tool', 3),
  ('flooring-nailer', 'tool', NULL, 'Flooring Nailer', 'Pneumatic cleat nailer sized for tongue-and-groove hardwood and engineered boards. Pairs with a jobsite compressor for fast, consistent fastening.', 'Power Tool', 3),
  ('flooring-pull-bar', 'tool', NULL, 'Flooring Pull Bar', 'Steel pull bar with a hooked end that closes joints on the last row and end planks against the wall. It lets a mallet pull boards tight where a tapping block has no room to swing.', 'Hand Tool', 2),
  ('flooring-spacers', 'tool', NULL, 'Flooring Spacer', 'Reusable plastic spacers that hold an even expansion gap between flooring and walls, cabinets, and fixed objects. The gap lets wood and laminate swell with humidity without buckling, and trim covers it after install.', 'Other', 2),
  ('flooring-tapping-block', 'tool', NULL, 'Flooring Tapping Block', 'Hard plastic tapping block that closes plank joints without chipping the tongue or edge. It spreads the mallet blow along the plank, so boards seat tight and flush instead of splintering.', 'Hand Tool', 2),
  ('foam-board-backer', 'material', NULL, 'Foam Board Backer', 'Rigid foam board used as a sacrificial cutting backer under tile on saw tables.', 'Components', NULL),
  ('foam-cutting-board', 'material', NULL, 'Foam Board', 'Rigid 2 x 2 ft foam panel that gives tile a flat, cushioned surface for scoring and snapping. Supports the full tile during a cut and protects finished floors underneath.', 'Components', NULL),
  ('garden-hose-splitter', 'tool', NULL, 'Garden Hose Splitter', 'Y-splitter for connecting supply hose to the pressure washer while keeping a second line free for bucket fill or pump sprayer.', 'Other', 1),
  ('grout-brush', 'tool', NULL, 'Grout Brush', 'Stiff-bristle brush with a narrow head sized for grout joints, inside corners, and textured tile. Scrubs out grout haze and residue that a sponge rides over.', 'Hand Tool', 1),
  ('grouting-sponge', 'tool', NULL, 'Grouting Sponge', 'High-density grout sponge for washing and haze removal.', 'Hand Tool', 1),
  ('gutter-scoop', 'tool', NULL, 'Gutter Scoop', 'Curved scoop that clears leaves, shingle grit, and sludge from gutters and downspout openings. Its shape matches the gutter trough, so each pass lifts packed debris out in one grab.', 'Hand Tool', 1),
  ('hammer', 'tool', NULL, 'Hammer', 'Fiberglass-handle hammer for driving nails, demolition, and light prying. Head weight changes the job: the heavier framing hammer drives large nails and breaks up material, while the light hammer controls finish nails and small adjustments.', 'Hand Tool', 1),
  ('hand-float', 'tool', NULL, 'Hand Float', '12 x 3-1/8 in magnesium hand float with a wood handle for flattening and smoothing fresh mortar beds, concrete patches, and small slabs. The light, rigid blade glides over wet mix without grabbing and knocks down high spots before final troweling.', 'Hand Tool', 2),
  ('hand-tamper', 'tool', NULL, 'Hand Tamper', 'Compact the gravel and soil around posts before and after concrete.', 'Hand Tool', 2),
  ('hedge-trimmer', 'tool', NULL, 'Hedge Trimmer', 'Powered trimmer with long reciprocating blades that shear hedge and shrub faces in wide passes. Dual-action blades cut cleanly through leafy growth and small branches, leaving a flat, even face.', 'Power Tool', 2),
  ('hepa-dust-control-system', 'tool', NULL, 'HEPA Dust Control System', 'HEPA-filtered dust containment vacuum sized for dustless hardwood refinishing with drum and edger sanders.', 'Power Tool', 3),
  ('insulated-screwdriver-set', 'tool', NULL, 'Insulated Screwdriver Set', 'Insulated screwdrivers for terminal screws on outlets, switches, and breakers.', 'Hand Tool', 2),
  ('internal-pipe-cutter', 'tool', NULL, 'Internal Pipe Cutter', 'Drill-driven cutter that trims plastic pipe from inside the bore. Spring-loaded blades expand against the pipe wall, cutting a drain body or stub flush with the floor or fitting where outside access is blocked.', 'Hand Tool', 3),
  ('knee-kicker', 'tool', NULL, 'Knee Kicker', 'Carpet knee kicker for stretching carpet into place along walls and into corners.', 'Hand Tool', 3),
  ('landscape-rake', 'tool', NULL, 'Landscape Rake', 'Landscape rake with a 36 in aluminum head and short, closely spaced tines for finish grading topsoil, loam, and fine fill before seed or sod. The wide, straight head pulls soil off high spots into low ones in a single pass, leaving a flat, even grade across large areas.', 'Hand Tool', 2),
  ('lawn-aerator', 'tool', NULL, 'Lawn Aerator', 'Walk-behind core aerator with hollow tines that pull plugs of soil out of the lawn. Open cores relieve compaction and let water, air, fertilizer, and seed reach the root zone.', 'Power Tool', 3),
  ('lawn-dethatcher', 'tool', NULL, 'Lawn Dethatcher', 'Power rake with spinning steel tines that lift dead thatch out of the turf. Clearing the thatch layer opens the soil surface so water, fertilizer, and new seed can reach it.', 'Power Tool', 3),
  ('leaf-vacuum', 'tool', NULL, 'Leaf Vacuum', 'Walk-behind leaf vacuum that pulls leaves through an impeller, shreds them, and fills a collection bag. Shredding shrinks the pile, so fewer bags go to the curb.', 'Power Tool', 2),
  ('leveling-laser', 'tool', NULL, 'Leveling Laser', 'Self-leveling cross-line laser that projects straight, level, and square reference lines across floors and walls. It holds those lines across an entire room, which keeps tile rows, cabinets, and trim aligned.', 'Power Tool', 2),
  ('log-splitter', 'tool', NULL, 'Log Splitter', 'Hydraulic splitter that drives rounds against a steel wedge to split them into firewood. Tonnage sets how hard the ram pushes, and higher tonnage keeps dense oak and hickory moving without stalling.', 'Power Tool', 3),
  ('manual-tile-cutter', 'tool', NULL, 'Manual Tile Cutter', 'Manual snap tile cutter that scores and snaps ceramic and porcelain in one straight line, with no water, dust, or power. Cut length sets the largest tile each cutter handles.', 'Hand Tool', 3),
  ('measuring-pitcher', 'tool', NULL, 'Measuring Pitcher', 'Graduated measuring pitcher for adding water and liquid additives to mortar, grout, and leveler. Accurate water ratios set each batch''s strength and working time.', 'Other', 1),
  ('mini-paint-roller', 'tool', NULL, 'Mini Paint Roller', '4 in mini roller frame and cover for doors, cabinets, shelving, and narrow trim. The small cover holds less paint and rolls a thin, even coat on surfaces where a 9 in roller overlaps the edges.', 'Hand Tool', 1),
  ('mini-scaffold', 'tool', NULL, 'Mini Scaffold', 'Compact interior scaffold platform for painting and trim work where a ladder feels tippy.', 'Other', 3),
  ('miter-clamp-kit', 'tool', NULL, 'Miter Clamp Kit', 'Spring miter clamp kit with four micro-point clamps and spreading pliers for holding glued trim corners closed. The clamps open to 2 in and grip the joint while adhesive cures, where bar clamps cannot get a hold.', 'Hand Tool', 3),
  ('miter-shears', 'tool', NULL, 'Miter Shears', 'Hand shears with an angle guide for cutting wood quarter round and shoe molding at the wall. Set the stop for a square corner or a soft corner, then squeeze for a clean shear cut without a chop saw or dust.', 'Hand Tool', 3),
  ('mortar-mixer', 'tool', NULL, 'Mortar and Grout Mixer', 'Low-speed paddle mixer for thinset, grout, joint compound, and self-leveler. The slow speed blends batches to a smooth, consistent texture without whipping in air that weakens the mix.', 'Power Tool', 2),
  ('non-contact-voltage-tester', 'tool', NULL, 'Non-Contact Voltage Tester', 'Pen-style voltage tester that detects live wires, outlets, and cords without touching bare conductors. Lights and beeps near voltage, confirming a circuit is off before work starts.', 'Hand Tool', 1),
  ('oscillating-blade', 'material', NULL, 'Oscillating Blade', 'Replacement oscillating blades for grout and flush cuts.', 'Consumables', NULL),
  ('oscillating-sander-set', 'tool', NULL, 'Oscillating Sander Set', 'Detail sanding pad set that mounts on an oscillating multi-tool for corners, trim profiles, and tight spots. The triangular pad reaches into inside corners that round orbital sanders cannot.', 'Power Tool', 2),
  ('paint-brush', 'tool', NULL, 'Paint Brush', 'Professional paint brushes in angled and flat styles for cutting in, trim, and detail work. Tapered bristles hold a load of paint and release it in a steady line, leaving crisp edges without heavy brush marks.', 'Hand Tool', 1),
  ('paint-bucket-opener', 'tool', NULL, 'Paint Bucket Opener', 'Steel lid wrench that pries off 1 gal and 5 gal paint lids without bending the rim. A shaped hook grips under the lid edge, so the lid seals tight again after use.', 'Hand Tool', 1),
  ('paint-edge-guard', 'tool', NULL, 'Paint Edge Guard', 'Wide shield held against ceilings, carpet, and trim while rolling or brushing. The straight edge blocks paint from the adjacent surface, cutting a clean line without masking tape.', 'Hand Tool', 2),
  ('paint-edger-tool', 'tool', NULL, 'Paint Edger Tool', 'Pad-style paint edger with guide wheels that ride along ceilings and trim. The wheels hold the pad a fixed distance from the adjacent surface, laying a straight cut line without a brush or tape.', 'Hand Tool', 2),
  ('paint-mix-sticks', 'material', NULL, 'Paint Mix Sticks', 'Flat wooden stir sticks for hand-mixing paint, primer, and stain in cans and small pails. The flat blade lifts settled pigment from the bottom of the can back into the mix for even color and sheen.', 'Consumables', NULL),
  ('paint-mixer-paddle', 'tool', NULL, 'Paint Mixer Paddle', 'Helix mixing paddle that chucks into a drill to blend paint, primer, and patch compound in buckets. The helix blade pulls material from the bottom up without whipping air into the mix.', 'Other', 2),
  ('paint-pail', 'tool', NULL, 'Paint Pail', '32 oz hand pail with a grip handle for carrying cut-in paint up a ladder. A smaller load is lighter to hold and keeps the brush loaded evenly along long cut lines.', 'Other', 1),
  ('paint-pail-liner', 'material', NULL, 'Paint Pail Liner', 'Disposable plastic liners that fit 32 oz cut-in pails. The liner holds the paint, so switching colors or finishing for the day means lifting out the liner instead of scrubbing the pail.', 'Consumables', NULL),
  ('paint-roller-cover', 'material', NULL, 'Paint Roller Cover', '9 in paint roller covers in nap depths from 1/4 in to 3/4 in. Short nap lays a smooth finish on flat walls and doors, while longer nap reaches into texture, stucco, and rough siding.', 'Consumables', NULL),
  ('paint-roller-frame', 'tool', NULL, 'Paint Roller Frame', '9 in paint roller frame with a steel cage that holds standard roller covers and threads onto extension poles. The cage spins freely on its bearing, letting the cover roll straight without skidding or leaving ridges.', 'Hand Tool', 1),
  ('paint-roller-stick', 'tool', NULL, 'Paint Roller Stick', 'Threaded roller handle that fits standard 9 in roller frames and extension poles. A rigid shaft and secure threads keep the roller tracking straight under pressure on walls and ceilings.', 'Hand Tool', 1),
  ('paint-roller-tray', 'tool', NULL, 'Paint Roller Tray', 'Reusable deep-well tray sized for 9 in roller covers. Ribbed ramps spread paint evenly across the nap, loading the cover fully without flooding it.', 'Hand Tool', 1),
  ('paint-roller-tray-liner', 'material', NULL, 'Paint Roller Tray Liner', 'Disposable plastic inserts that fit 9 in paint roller trays. The liner holds the paint, so color changes and end-of-day cleanup mean swapping a liner instead of scrubbing the tray.', 'Consumables', NULL),
  ('paint-scraper', 'tool', NULL, 'Paint Scraper', 'Wide-blade scraper with a stiff steel blade that lifts loose, peeling, and failing paint from wood, trim, and siding. A sharp, rigid edge removes coatings down to sound paint without gouging the surface below.', 'Hand Tool', 1),
  ('paint-strainer', 'material', NULL, 'Paint Strainer', 'Fine mesh strainer bags that filter lumps, skin, and debris out of paint before it reaches a tray or sprayer. Clean paint rolls smooth and keeps sprayer tips and filters from clogging.', 'Consumables', NULL),
  ('paint-thinner-eco', 'material', NULL, 'Paint Thinner', 'Low-odor paint thinner that cleans oil-based paint, stain, and varnish from brushes, rollers, and tools. It dissolves wet oil-based coatings with less odor than standard mineral spirits.', 'Consumables', NULL),
  ('painters-multi-tool', 'tool', NULL, 'Painters Multi-Tool', 'Stainless steel 5-in-1 painter''s tool with a scraping blade, putty edge, can opener, and roller-cleaning curve. One stiff tool opens lids, scrapes loose paint, spreads patching compound, and squeezes paint from roller covers.', 'Hand Tool', 1),
  ('painting-extension-pole', 'tool', NULL, 'Painting Extension Pole', 'Telescoping extension pole that threads onto roller frames and brushes for tall walls and ceilings. Positive locks hold the pole at length, keeping the roller steady and pressure even from the floor.', 'Hand Tool', 1),
  ('plastic-bags-gallon', 'material', NULL, 'Plastic Bags', 'Gallon zip-top plastic bags that seal airtight around wet brushes, roller covers, and small parts. Sealing out air keeps latex paint from drying on tools overnight between coats.', 'Consumables', NULL),
  ('plate-joiner', 'tool', NULL, 'Plate Joiner', 'Plate joiner, also called a biscuit joiner, that cuts matching oval slots for glued wooden biscuits. The biscuits align boards in edge glue-ups so tabletops, bench tops, and panels stay flush.', 'Power Tool', 3),
  ('pocket-hole-jig', 'tool', NULL, 'Pocket Hole Jig', 'Drilling jig that bores angled pocket holes for screwed butt joints. Pocket screws pull the joint tight from the hidden side, making strong frames without complex joinery.', 'Hand Tool', 3),
  ('pocket-screw', 'material', NULL, 'Pocket Screw', 'Pocket-hole screws with flat-bottom washer heads and self-tapping tips that seat in a pocket hole and pull the joint tight, in coarse and fine threads. Coarse thread grips softwood and plywood, fine thread grips hardwood, and length matches the stock thickness.', 'Components', NULL),
  ('pole-saw', 'tool', NULL, 'Pole Saw', 'Telescoping pole saw with a cutting head that reaches high limbs from the ground. Extending the pole puts overhead branches within reach without climbing a ladder.', 'Power Tool', 2),
  ('portable-work-bench', 'tool', NULL, 'Portable Work Bench', 'Folding portable work bench that sets up a stable, waist-high surface for cutting, clamping, and staging materials. Folds flat for carrying between rooms and for storage.', 'Other', 2),
  ('portable-work-light', 'tool', NULL, 'Portable Work Light', 'Portable LED work light that floods a room or work area with bright, even light for layout, painting, and inspection. Power source sets the style: a plug-in tripod light for whole rooms or a compact battery light for tight spots.', 'Other', 1),
  ('post-hole-auger', 'tool', NULL, 'Post Hole Auger', 'Gas powerhead with interchangeable earth auger bits that bore round post holes into soil. The spiral flighting lifts dirt out as it drills, digging far faster than a manual clamshell digger.', 'Power Tool', 3),
  ('post-hole-digger', 'tool', NULL, 'Post Hole Digger', 'Manual clamshell digger for starting holes, cleaning sides, and working around roots.', 'Hand Tool', 2),
  ('ppe-ear-plugs-disp', 'material', NULL, 'Disposable Ear Plugs', 'Disposable foam ear plugs that expand to seal the ear canal and cut noise from engines, saws, and blowers. The soft foam stays comfortable through long sessions and is thrown away after the job.', 'PPE', NULL),
  ('pressure-washer-extension-wand', 'tool', NULL, 'Pressure Washer Wand Extension', 'Telescoping lance for reaching second-story siding, soffits, and gutter lines. A six-foot extension wand cuts down on ladder trips.', 'Other', 3),
  ('pressure-washer-hose-extension', 'tool', NULL, 'Pressure Washer Hose Extension', 'High-pressure hose extension that couples between the washer and the spray gun to reach the far side of driveways, decks, and house walls. The added length lets the washer stay parked in one spot while the wand moves.', 'Other', 3),
  ('pressure-washer-nozzle-set', 'tool', NULL, 'Pressure Washer Nozzle Set', 'Quick-connect spray tips for fan, pinpoint, and soap modes. Extra tips matter because the right one always disappears mid-job.', 'Other', 3),
  ('propane-forced-air-heater', 'tool', NULL, 'Propane Forced-Air Heater', 'Portable propane torpedo heater for garages, open work areas, and well-ventilated job spaces. Hose and regulator connect to a standard propane tank (tank not included). Use only outdoors or with continuous fresh air; not in living spaces.', 'Other', 3),
  ('pump-sprayer', 'tool', NULL, 'Pump Sprayer', 'Hand-pump sprayer for applying house wash and mold treatments evenly before rinsing. Useful where low-pressure chemical application is safer than spraying through the washer.', 'Hand Tool', 2),
  ('pvc-cement', 'material', NULL, 'PVC Cement', 'Clear solvent cement that fuses primed PVC pipe and fittings into a single welded joint. It softens both mating surfaces, so pipe and fitting cure as one piece instead of relying on a surface glue bond.', 'Consumables', NULL),
  ('pvc-pipe-cutter', 'tool', NULL, 'PVC Pipe Cutter', 'Ratcheting pipe cutter that slices PVC and other plastic pipe with a single sharp blade. Square cuts let solvent-weld joints seat fully in the fitting socket, with no saw dust or ragged edges to clean up.', 'Hand Tool', 2),
  ('pvc-primer', 'material', NULL, 'PVC Primer', 'Purple primer that cleans and softens PVC before solvent cement. The tint shows code inspectors that the joint was primed.', 'Consumables', NULL),
  ('quick-clamp', 'tool', NULL, 'Quick Clamp', 'One-handed bar clamp with non-marring pads that holds jigs, templates, and doors in place. A trigger ratchets the jaw closed and a release lever frees it for quick repositioning.', 'Hand Tool', 1),
  ('respirator', 'tool', NULL, 'Face Mask', 'Disposable dust masks that filter fine particles from sanding, tile cutting, sweeping, and dusty demolition. A molded shell and nose clip seal against the face, so dust stays out without a heavy respirator.', 'PPE', 2),
  ('roofing-nailer', 'tool', NULL, 'Roofing Nailer', 'Coil roofing nailer for fastening asphalt shingles into decking at consistent depth.', 'Power Tool', 3),
  ('rubber-boots', 'tool', NULL, 'Rubber Boots', 'Waterproof rubber boots that keep feet dry in runoff, puddles, mud, and standing water during wet outdoor work. The one-piece rubber shell blocks water that soaks through leather and fabric work boots.', 'PPE', 1),
  ('rubber-gloves', 'material', NULL, 'Rubber Gloves', 'Reusable rubber gloves for wet grout cleanup.', 'PPE', NULL),
  ('sanding-sponge', 'material', NULL, 'Sanding Sponge', 'Foam-core sanding sponges coated with abrasive on multiple faces for hand sanding. The flexible foam conforms to edges, corners, and profiles that flat sandpaper skips.', 'Consumables', NULL),
  ('screwdriver', 'tool', NULL, 'Screwdriver', 'Hand screwdriver in fixed flathead and interchangeable multi-bit types for cover plates, cabinet hardware, and fixture fasteners. Multi-bit drivers swap Phillips, slotted, and square tips in one handle, and the magnetic version holds the screw on the bit.', 'Hand Tool', 1),
  ('screwdriver-bit-set', 'tool', NULL, 'Screwdriver Bit Set', 'Driver bit set with the common Phillips, slotted, and square tips for drill drivers and impact drivers. Covers the screws on backer board, hardware, fixtures, and cover plates.', 'Hand Tool', 1),
  ('seam-roller', 'tool', NULL, 'Seam Roller', 'Weighted hand roller for pressing uncoupling membrane and seam tape into fresh thinset. Even pressure beds the sheet fully and pushes out air pockets that would leave hollow spots under tile.', 'Hand Tool', 3),
  ('shower-drain-test-plug', 'tool', NULL, 'Drain Test Plug', 'Expandable test plug that seals a shower drain body so the pan holds standing water for a flood test. A compression seal locks inside the drain, holding water at full test depth without tape or improvised stoppers.', 'Other', 3),
  ('siding-nailer', 'tool', NULL, 'Siding Nailer', 'Coil siding nailer for fastening vinyl, fiber-cement, and wood siding courses cleanly into studs.', 'Power Tool', 3),
  ('sledge-hammer', 'tool', NULL, 'Sledge Hammer', 'Drive stakes, set posts, and seat hardware with controlled heavy blows.', 'Hand Tool', 2),
  ('soft-wash-brush', 'tool', NULL, 'Soft Wash Brush', 'Soft-bristle wash brush that scrubs house wash into delicate siding, painted trim, and composite decking without gouging. Dense, soft bristles hold cleaning solution against the surface and lift film that a low-pressure rinse would miss.', 'Hand Tool', 2),
  ('stiff-scrub-brush', 'tool', NULL, 'Stiff Scrub Brush', 'Stiff-bristle hand brush for agitating cleaner on stubborn stains, deck boards, and concrete spots that will not rinse away with spray alone.', 'Hand Tool', 1),
  ('string-line', 'tool', NULL, 'String Line', 'Snap a straight fence run and keep posts aligned before digging.', 'Hand Tool', 1),
  ('tape-measure-digital', 'tool', NULL, 'Digital Tape Measure', '25 ft digital tape measure with a dual-screen readout and rechargeable battery that displays each measurement as the blade extends. Reading the number on a screen removes fraction errors on repeat cuts and long layout runs.', 'Hand Tool', 2),
  ('tarp', 'tool', NULL, 'Tarp', 'Heavy-duty polyethylene tarps with reinforced grommeted edges for covering, masking, and hauling. The tough woven fabric protects shrubs, walkways, and floors from paint, water, and debris, and drags loaded piles across a yard.', 'Other', 1),
  ('tear-off-shovel', 'tool', NULL, 'Tear-Off Shovel', 'Roofing tear-off shovel with notched blade for lifting shingles and nails from the deck.', 'Hand Tool', 3),
  ('thinset-mortar', 'material', NULL, 'Thinset Mortar', 'Polymer-modified thinset mortar that bonds tile to floors, walls, cement board, and uncoupling membrane. Polymers add flexibility and grip, so tile holds through the small movements that crack unmodified mortar.', 'Consumables', NULL),
  ('tile-addon-gauge-rake', 'tool', NULL, 'Gauge Rake', 'Gauge rake with adjustable depth pins for spreading self-leveling underlayment to an even thickness. The pins ride on the subfloor, so the pour spreads to the set depth across the whole floor.', 'Hand Tool', 3),
  ('tile-addon-spiked-shoes', 'tool', NULL, 'Spiked Shoes', 'Strap-on spiked shoe covers for working across wet self-leveling underlayment without sinking in or leaving footprints. The narrow spikes displace only small points of material, which level back in as the pour settles.', 'PPE', 3),
  ('tile-glass-suction-cup', 'tool', NULL, 'Suction Cup Lifter', 'Lever-lock vacuum cups for lifting and placing smooth tile, stone, and glass without gripping the edges. The rubber cup seals against non-porous faces, so large pieces set without finger marks or pinched edges.', 'Hand Tool', 2),
  ('tile-leveling-cap', 'tool', NULL, 'Tile Leveling Cap', 'Reusable threaded spin caps that tighten onto leveling clip posts to pull adjacent tiles flush. Even pressure across each joint prevents lippage, the uneven tile edges that catch light and toes.', 'Hand Tool', 3),
  ('tile-puck', 'tool', NULL, 'Tile Puck', 'Handled suction puck for lifting and placing large-format tile without touching the mortar or edges. Gives a secure grip on smooth faces for setting heavy tile flat and level.', 'Hand Tool', 3),
  ('tile-spacer', 'material', NULL, 'Tile Spacer', 'Cross-shaped plastic spacers that hold tile at an even grout joint width while thinset cures. Consistent joints keep rows straight and grout lines uniform across the floor or wall.', 'Consumables', NULL),
  ('timer', 'tool', NULL, 'Timer', 'Digital countdown timer for tracking mortar pot life, grout haze windows, and finish recoat times. Clear alarms keep mixed batches from setting up in the bucket and haze from hardening on tile.', 'Other', 1),
  ('toilet-lifter-handle', 'tool', NULL, 'Toilet Lifter Handle', 'Spring-loaded handle that clamps under the toilet bowl rim to lift, carry, and set the toilet with a secure grip. Keeps hands away from the wax ring and water line while lining up the closet bolts.', 'Hand Tool', 3),
  ('trash-can', 'tool', NULL, 'Trash Can', 'Heavy-duty plastic trash can for collecting offcuts, packaging, and debris as work goes. Keeping scrap in one container clears the floor and turns cleanup into a single trip to the curb.', 'Other', 1),
  ('trim-pry-tool', 'tool', NULL, 'Trim Pry Tool', 'Flat pry tool for removing baseboard and trim before tile.', 'Hand Tool', 1),
  ('trim-puller', 'tool', NULL, 'Trim Puller', 'Flat trim removal tool that pries baseboard, casing, and shoe molding away from the wall without gouging drywall. The wide face spreads pressure across the wall, so trim comes off intact for reuse.', 'Hand Tool', 2),
  ('tub-drain-wrench', 'tool', NULL, 'Tub Drain Wrench', 'Dual-ended tub drain wrench that grips crossbar and crossbar-free drain flanges to install or remove them without scratching the finish. Accepts a 3/8 or 1/2 in ratchet, an adjustable wrench, or a screwdriver for leverage and is tested to 100 ft-lb.', 'Hand Tool', 3),
  ('vinyl-flooring-adhesive', 'material', NULL, 'Vinyl Flooring Adhesive', 'Pressure-sensitive adhesive for glue-down luxury vinyl plank when the floor type requires it.', 'Consumables', NULL),
  ('vinyl-flooring-cutter', 'tool', NULL, 'Vinyl Flooring Cutter', 'Score-and-snap cutter for luxury vinyl plank and tile cuts without dust or power tools.', 'Hand Tool', 3),
  ('vinyl-siding-brake', 'tool', NULL, 'Vinyl Siding Brake', 'Portable brake that bends vinyl starter strips, J-channel returns, and corner pieces on site.', 'Other', 3),
  ('wall-wash-concentrate', 'material', NULL, 'Wall Wash Concentrate', 'Concentrated wall wash for chalky dust, light soot, and general grime before primer on interior drywall and plaster.', 'Consumables', NULL),
  ('wallpaper-scraper', 'tool', NULL, 'Wallpaper Scraper', 'Wide blade scraper for lifting softened wallpaper and adhesive without gouging drywall.', 'Hand Tool', 2),
  ('wallpaper-steamer', 'tool', NULL, 'Wallpaper Steamer', 'Steamer for softening adhesive and lifting wallpaper without gouging drywall.', 'Power Tool', 3),
  ('waterproof-coveralls', 'tool', NULL, 'Waterproof Coveralls', 'Full-zip waterproof coveralls that cover work clothes from collar to ankle during spray, runoff, and wet outdoor work. Waterproof fabric sheds water and mud, so long wash days end dry instead of soaked through.', 'PPE', 2),
  ('wax-pencil', 'material', NULL, 'Wax Pencil', 'Wax marking pencil that draws visible lines on glazed tile, glass, stone, and metal. The wax shows on dark and glossy surfaces and wipes off after cutting.', 'Consumables', NULL),
  ('wet-floor-sign', 'tool', NULL, 'Wet Floor Sign', 'Freestanding folding sign that warns of wet floors, fresh grout, and newly finished surfaces. Keeps people off curing work until it can take foot traffic.', 'Other', 1),
  ('wire-stripper', 'tool', NULL, 'Wire Stripper', 'Combination stripper and cutter for 10 to 22 AWG solid and stranded wire.', 'Hand Tool', 1),
  ('wood-chisel-set', 'tool', NULL, 'Wood Chisel Set', 'Bevel-edge wood chisels in graduated widths for cleaning joints, fitting parts, and paring glue. Beveled sides reach into corners and tight joints where a square-edge chisel cannot.', 'Hand Tool', 2),
  ('wood-sandpaper', 'material', NULL, 'Wood Sandpaper', 'Assorted-grit sanding discs and sheets for random orbital and hand sanding. Coarse grits remove mill marks, and fine grits prep surfaces for stain and clear finish.', 'Consumables', NULL),
  ('acrylic-bathtub', 'material', NULL, 'Acrylic Bathtub', 'Acrylic alcove bathtub with a finished tub surface and a tiling flange on three sides. Wall tile laps over the flange so shower water runs into the tub instead of behind it.', 'Components', NULL),
  ('acrylic-shower-base', 'material', NULL, 'Acrylic Shower Base', 'One-piece acrylic or composite shower pan with a molded slope, finished surface, and built-in threshold. Serves as the finished shower floor, with tile or panels on the walls above its flange.', 'Components', NULL),
  ('asphalt-shingles', 'material', NULL, 'Asphalt Shingles', 'Architectural or 3-tab asphalt shingle bundles for the roof field and hips.', 'Components', NULL),
  ('bar-and-chain-oil', 'material', NULL, 'Bar and Chain Oil', 'Tacky lubricating oil that feeds from the chainsaw''s reservoir onto the bar and chain while it runs. The tackifier keeps oil on the chain at full speed, cutting friction and heat so the bar and chain wear slower.', 'Consumables', NULL),
  ('board-seam-sealant', 'material', NULL, 'Board Seam Sealant', 'Flexible waterproof sealant in cartridge tubes for seams, inside corners, and fastener heads on waterproof backer board. Cures into a bonded, watertight joint that moves with the board without cracking.', 'Consumables', NULL),
  ('broadcast-spreader', 'tool', NULL, 'Broadcast Spreader', 'Push spreader with a hopper and spinning plate that throws seed, fertilizer, and pellets across a wide, even band. An adjustable gate meters the flow so coverage matches the rate on the bag.', 'Hand Tool', 2),
  ('carpet-broadloom', 'material', NULL, 'Carpet Broadloom', 'Wall-to-wall carpet sold by the square yard or roll. Buy locally to match style and pile.', 'Components', NULL),
  ('carpet-pad', 'material', NULL, 'Carpet Pad', 'Cushion pad under broadloom carpet. Buy locally by thickness and density.', 'Components', NULL),
  ('carpet-seam-tape', 'material', NULL, 'Carpet Seam Tape', 'Heat-activated seam tape for joining carpet widths with a seaming iron.', 'Consumables', NULL),
  ('carpet-tack-strip', 'material', NULL, 'Carpet Tack Strip', 'Wood tack strip with pins that holds stretched carpet at the walls.', 'Components', NULL),
  ('caulk', 'material', NULL, 'Caulk', 'Gun-grade caulk in acrylic latex, exterior sealant, silicone, and polyurethane formulas for sealing gaps, joints, and seams around trim, tile, windows, and siding. The formula decides what it bonds to, whether it takes paint, and how much movement and weather the bead can handle.', 'Consumables', NULL),
  ('cement-board', 'material', NULL, 'Cement Board', 'Cement backer board that gives tile a stable, water-resistant base on floors and walls. Unlike drywall or plywood, it does not swell or break down when wet, which keeps tile bonded in showers and on floors.', 'Components', NULL),
  ('cement-board-screw', 'material', NULL, 'Cement Board Screw', 'Corrosion-resistant screws with wide, ribbed heads for fastening cement backer board to wood subfloors and studs. The ribs cut their own countersink, so heads sit flush without tearing the board face.', 'Components', NULL),
  ('chain-link-fabric', 'material', NULL, 'Chain Link Fabric', 'Galvanized chain-link mesh rolled for residential fence runs.', 'Components', NULL),
  ('chain-link-tension-wire', 'material', NULL, 'Chain Link Tension Wire', 'Bottom and top tension wire that keeps chain-link fabric from sagging.', 'Components', NULL),
  ('concrete-cleaner', 'material', NULL, 'Concrete Cleaner', 'Concrete and masonry cleaner for oil spots, tire marks, and weather staining on driveways, garage floors, and walkways. Degreasers lift oil out of the pores of the concrete so rinsing clears stains that water alone leaves behind.', 'Consumables', NULL),
  ('deck-framing-lumber', 'material', NULL, 'Deck Framing Lumber', 'Pressure-treated dimensional lumber for joists, beams, ledgers, and blocking. Framing lumber carries the deck''s load down to the posts and footings.', 'Components', NULL),
  ('deck-mud', 'material', NULL, 'Deck Mud', 'Dry-pack mortar of sand and portland cement for sloped shower pans and thick floor mortar beds. Packs firm with little water, so the bed holds its slope and cures into a solid base for tile.', 'Consumables', NULL),
  ('deck-post-footings', 'material', NULL, 'Deck Post and Footing Kit', 'Posts, post bases, and footing forms that carry the deck down to frost depth. Footings below the frost line keep the deck from heaving through New England winters.', 'Components', NULL),
  ('deck-railing-kit', 'material', NULL, 'Deck Railing Kit', 'Posts, balusters, and rail stock for a code-height guard rail around the deck and stairs. A matched kit keeps baluster spacing and rail height consistent from end to end.', 'Components', NULL),
  ('deck-roofing-lumber', 'material', NULL, 'Deck and Roofing Lumber', 'Pressure-treated framing, decking boards, and shingle bundles for your plan.', 'Components', NULL),
  ('degreasing-cleaner', 'material', NULL, 'Degreasing Cleaner', 'Degreasing wall cleaner that removes cooking grease, handprints, and grime from walls, trim, and hard surfaces. Clean surfaces let primer, paint, and caulk bond instead of peeling where oils remain.', 'Consumables', NULL),
  ('door-shims', 'material', NULL, 'Door and Window Shims', 'Tapered shims for plumbing and leveling jambs in the rough opening.', 'Components', NULL),
  ('drainage-gravel', 'material', NULL, 'Drainage Gravel', 'Crushed stone under and around posts for drainage before concrete.', 'Components', NULL),
  ('drip-edge', 'material', NULL, 'Drip Edge', 'Metal drip edge for eaves and rakes that sheds water off the fascia.', 'Components', NULL),
  ('drywall-mesh-tape', 'material', NULL, 'Drywall Mesh Tape', 'Self-adhesive fiberglass mesh tape that reinforces drywall seams, cracks, and patch edges. The open weave sticks in place without a bedding coat and lets joint compound push through, locking the tape into the finished joint.', 'Consumables', NULL),
  ('drywall-repair-patch', 'material', NULL, 'Drywall Repair Patch', 'Self-adhesive patch with an aluminum plate and fiberglass mesh that bridges holes too large for spackle alone. The rigid plate supports joint compound over the gap, so the repair stays flat and does not crack or sag after paint.', 'Consumables', NULL),
  ('drywall-sandpaper', 'material', NULL, 'Drywall Sandpaper', 'Open-mesh sanding screens and sheets sized for drywall pole and hand sanders. The mesh lets joint compound dust fall through instead of clogging the abrasive, so each sheet keeps cutting through full rooms of seams.', 'Consumables', NULL),
  ('drywall-sheets', 'material', NULL, 'Drywall Sheets', 'Gypsum wallboard panels for new walls, ceilings, and large patch sections. A gypsum core faced with paper gives a flat, fire-resistant surface that takes tape, joint compound, and paint.', 'Components', NULL),
  ('electrical-box-shim', 'material', NULL, 'Electrical Box Shim', 'Caterpillar-style plastic box shims for flushing recessed outlets and switches to the finished wall surface.', 'Components', NULL),
  ('electrical-receptacle', 'material', NULL, 'Electrical Receptacle', 'Replacement duplex and GFCI receptacles for standard residential box swaps.', 'Components', NULL),
  ('electrical-switch', 'material', NULL, 'Electrical Switch', 'Replacement switches for single-pole, 3-way, and dimmer swaps in standard boxes.', 'Components', NULL),
  ('exterior-deck-stain', 'material', NULL, 'Exterior Deck Stain', 'Penetrating exterior stain and sealer for deck boards and railings. It soaks into the wood to repel water and slow UV graying.', 'Consumables', NULL),
  ('exterior-door-unit', 'material', NULL, 'Exterior Door Unit', 'Prehung exterior door unit with frame, sized for the rough opening.', 'Components', NULL),
  ('exterior-screw', 'material', NULL, 'Exterior Screw', 'Exterior wood screws with corrosion-resistant coated or stainless steel shanks, star drive heads, and self-drilling points for fences, gates, trim, and siding. Length sets how deep the screw bites into framing, and stainless resists the tannins in cedar and redwood that stain coated screws.', 'Components', NULL),
  ('exterior-siding-trim', 'material', NULL, 'Exterior Siding and Trim', 'Cladding panels, corner posts, J-channel, and trim stock bought to match your siding system.', 'Components', NULL),
  ('faceplate-screws', 'material', NULL, 'Faceplate Screws', 'White oval-head machine screws that fasten outlet and switch cover plates to electrical boxes. The standard 6-32 thread fits common boxes and devices, and the white head blends into white plates.', 'Components', NULL),
  ('fence-fasteners', 'material', NULL, 'Fence Fasteners', 'Exterior nails, screws, and ties sized for fence panels and rails.', 'Components', NULL),
  ('fence-gate-kit', 'material', NULL, 'Fence Gate Kit', 'Walk-gate frame hardware matched to your fence style.', 'Components', NULL),
  ('fence-posts', 'material', NULL, 'Fence Posts', 'Pressure-treated or matching posts set in concrete on 8 ft centers.', 'Components', NULL),
  ('fence-rails', 'material', NULL, 'Fence Rails', 'Horizontal rails that carry wood panels or pickets between posts.', 'Components', NULL),
  ('firewood', 'material', NULL, 'Firewood', 'Split, seasoned hardwood cut to stove and fireplace length. Seasoned wood has dried to a low moisture content, so it lights quickly and burns hot with less smoke.', 'Consumables', NULL),
  ('flashing-tape', 'material', NULL, 'Flashing Tape', 'Self-adhered flashing tape for sealing window and door rough openings.', 'Consumables', NULL),
  ('floor-polyurethane', 'material', NULL, 'Floor Polyurethane', 'Oil-modified floor polyurethane for durable top coats on sanded hardwood. Pick sheen and volume for your room size.', 'Consumables', NULL),
  ('floor-sanding-belt', 'material', NULL, 'Floor Sanding Belt', 'Cloth sanding belts for drum floor sanders. Match grit to cut vs finish passes.', 'Consumables', NULL),
  ('floor-sanding-disc', 'material', NULL, 'Floor Sanding Disc', 'Edger sanding discs for perimeter passes along walls and in closets.', 'Consumables', NULL),
  ('flooring-planks', 'material', NULL, 'Flooring Planks', 'Hardwood, engineered, or LVP planks sized to your room layout.', 'Components', NULL),
  ('flooring-staples', 'material', NULL, 'Flooring Staples', 'Collated flooring staples that load into pneumatic flooring staplers for engineered and solid hardwood installs. The staple crown holds the plank tongue tight to the subfloor so boards stay flat and quiet underfoot.', 'Components', NULL),
  ('foam-board-fastener', 'material', NULL, 'Foam Board Fastener', 'Corrosion-resistant screws paired with wide washers for fastening foam backer board to wood or steel studs. The broad washer spreads clamping force so the screw holds tight without crushing the foam.', 'Components', NULL),
  ('foam-shower-base', 'material', NULL, 'Foam Shower Base', 'Factory-sloped foam shower tray that replaces a mortar pan with a light, precisely pitched base for tile. Pairs with a matching drain and sheet membrane to form a fully waterproof tiled shower floor.', 'Components', NULL),
  ('furniture-lumber', 'material', NULL, 'Furniture Lumber', 'Dimensional hardwood and softwood stock for legs, aprons, rails, and solid tops. Straight, dry boards mill flat and hold joints tight as the piece ages.', 'Components', NULL),
  ('gasoline', 'material', NULL, 'Gasoline', 'Unleaded gasoline for four-stroke outdoor power equipment such as log splitters, tillers, and generators. Sold and billed by the US gallon.', 'Consumables', NULL),
  ('glue-sticks', 'material', NULL, 'Glue Sticks', 'Full-size hot melt glue sticks for dual-temperature glue guns. Clear amber sticks set in under a minute, holding cardboard and thin template stock steady for scribing.', 'Consumables', NULL),
  ('grass-seed', 'material', NULL, 'Grass Seed', 'Cool-season grass seed for overseeding thin turf and filling bare patches. Blends pair grasses suited to sun and shade so new growth fills in evenly through New England seasons.', 'Consumables', NULL),
  ('grout', 'material', NULL, 'Grout', 'Sanded grout for filling tile joints 1/8 in and wider on floors and walls. The sand content resists shrinking and cracking in wider joints, where unsanded grout pulls away.', 'Consumables', NULL),
  ('hardwood-flooring', 'material', NULL, 'Hardwood Flooring', 'Solid or engineered hardwood flooring planks in tongue-and-groove profiles for nail-down, staple-down, glue-down, or floating installs. Engineered planks layer hardwood over a plywood core for better stability over slabs and in humid rooms.', 'Components', NULL),
  ('house-wash-concentrate', 'material', NULL, 'House Wash Concentrate', 'Biodegradable house wash concentrate for vinyl and painted siding, soffits, and trim. Surfactants break down dirt, pollen, and mildew film so a low-pressure rinse carries it away without blasting the surface.', 'Consumables', NULL),
  ('house-wrap', 'material', NULL, 'House Wrap', 'Weather-resistive barrier rolled over sheathing before siding courses go up.', 'Components', NULL),
  ('interior-door', 'material', NULL, 'Interior Door', 'Prehung interior door units and door slabs for replacing or adding openings. Prehung units come mounted in a frame with the hinges set, and slabs hang in an existing frame.', 'Components', NULL),
  ('lawn-lime', 'material', NULL, 'Lawn Lime', 'Pelletized limestone that raises the pH of acidic soil. Balanced pH helps grass take up nutrients, and New England soils often run acidic.', 'Consumables', NULL),
  ('lawn-starter-fertilizer', 'material', NULL, 'Lawn Starter Fertilizer', 'Phosphorus-rich fertilizer made for new seed and recovering turf. The extra phosphorus feeds root growth so new grass establishes faster.', 'Consumables', NULL),
  ('lead-test-kit', 'material', NULL, 'Lead Test Kit', 'EPA-recognized swab kit that detects lead in paint on drywall, wood, plaster, and ferrous metal. Each swab turns red on contact with lead, giving an instant result before older paint is sanded or scraped.', 'Consumables', NULL),
  ('leaf-bags', 'material', NULL, 'Leaf Bags', 'Heavy paper yard-waste bags sized for leaves, clippings, and brush. Paper breaks down along with the contents, which is why most towns require it for curbside yard-waste pickup.', 'Consumables', NULL),
  ('liquid-waterproofing-membrane', 'material', NULL, 'Liquid Waterproofing Membrane', 'Roll-on elastomeric membrane that cures into a seamless, flexible waterproof layer over cement board, mortar beds, and concrete. Bridges hairline cracks and board seams so water stays out of the wall and floor behind the tile.', 'Consumables', NULL),
  ('lumber-and-trim', 'material', NULL, 'Lumber and Trim', 'Dimensional lumber, trim profiles, and panel stock for interior carpentry. Casing, baseboard, and crown profiles finish the joints between walls, floors, ceilings, and openings.', 'Components', NULL),
  ('lvp-planks', 'material', NULL, 'LVP Planks', 'Click-lock planks that make rooms look finished overnight', 'Components', NULL),
  ('mold-mildew-remover', 'material', NULL, 'Mold and Mildew Remover', 'Outdoor mold and mildew treatment for shaded siding, north-facing walls, fences, and damp deck boards. It kills green and black growth at the surface so a rinse lifts the stain instead of just thinning it.', 'Consumables', NULL),
  ('paint', 'material', NULL, 'Paint', 'Finish paint for walls, ceilings, and trim in a range of colors and sheens. Flat and matte sheens hide surface flaws, while satin and semi-gloss resist scuffs and wipe clean in kitchens, baths, and trim.', 'Consumables', NULL),
  ('pine-fence-panels', 'material', NULL, 'Pine Fence Panels', 'Pressure-treated pine privacy panels for a solid backyard fence face.', 'Components', NULL),
  ('pressure-treated-deck-boards', 'material', NULL, 'Pressure-Treated Deck Boards', 'Ground-contact rated pressure-treated boards for the deck''s walking surface. Treated lumber resists rot and insects where boards stay damp.', 'Components', NULL),
  ('primer', 'material', NULL, 'Primer', 'Bonding undercoat applied before finish paint. Primer improves adhesion, helps prevent peeling later, and gives better hide and a smoother surface for color coats.', 'Consumables', NULL),
  ('project-plywood', 'material', NULL, 'Project Plywood', 'Cabinet-grade or sanded plywood for shelves, backs, and panel tops. Cross-laminated plies stay flat and stable across wide panels where solid boards would cup.', 'Components', NULL),
  ('push-in-connector', 'material', NULL, 'Push In Connector', 'Push-in wire connectors for quick solid-wire joins when allowed in your box.', 'Components', NULL),
  ('pvc-fence-brackets', 'material', NULL, 'PVC Fence Brackets', 'Vinyl rail brackets and post caps that lock PVC panels in place.', 'Components', NULL),
  ('pvc-fence-panels', 'material', NULL, 'PVC Fence Panels', 'Vinyl privacy panels that stay bright with low yearly upkeep.', 'Components', NULL),
  ('ready-mix-concrete', 'material', NULL, 'Ready-Mix Concrete', 'Bagged concrete for setting posts below the frost line.', 'Consumables', NULL),
  ('roofing-nails', 'material', NULL, 'Roofing Nails', 'Coil roofing nails matched to your nailer and shingle thickness.', 'Components', NULL),
  ('roofing-underlayment', 'material', NULL, 'Roofing Underlayment', 'Synthetic or felt underlayment rolled over decking before shingles.', 'Components', NULL),
  ('sanding-pads-5in', 'material', NULL, 'Sanding Discs', '5 in hook-and-loop sanding discs for random orbital sanders, in coarse to fine grits. The hook-and-loop backing swaps grits in seconds, moving from stripping to between-coat scuffing on one pad.', 'Consumables', NULL),
  ('setting-joint-compound', 'material', NULL, 'Setting Joint Compound', 'Powder setting-type joint compound that hardens by chemical reaction instead of drying. It sets on a fixed schedule even in deep fills and humid rooms, so repairs can be sanded and recoated the same day.', 'Consumables', NULL),
  ('shower-drain', 'material', NULL, 'Shower Drain', 'Shower drain body and grate that connect a shower base or tiled pan to the 2 in drain line. Styles match the base: compression drains for acrylic pans, clamping-ring or bonding-flange drains for tiled floors.', 'Components', NULL),
  ('shower-pan-liner', 'material', NULL, 'Shower Pan Liner', 'Flexible PVC or CPE sheet membrane that lines a mortar shower pan and turns up the walls and curb to hold water. Clamps into the drain so water that soaks through the top mortar bed drains away instead of reaching the subfloor.', 'Components', NULL),
  ('siding-nails', 'material', NULL, 'Siding Nails', 'Coil nails matched to your siding nailer and cladding thickness.', 'Components', NULL),
  ('structural-screw', 'material', NULL, 'Structural Screw', 'Structural wood screws with a 0.220 in shank, large washer head, and double-barrier coating that replace lag screws and through-bolts in framing and treated lumber. Length matches the stack being joined, from doubled joists up to beams and ledgers.', 'Components', NULL),
  ('surface-cleaner', 'material', NULL, 'Surface Cleaner', 'Rotary surface cleaner attachment for flat work. Makes large driveways, patios, and garage floors faster than fan-spraying inch by inch.', 'Consumables', NULL),
  ('tack-cloth', 'material', NULL, 'Tack Cloth', 'Sticky tack cloth for wiping dust between sanding and finish coats.', 'Consumables', NULL),
  ('transition-strip', 'material', NULL, 'Transition Strip', 'Metal transition strips that bridge doorways and height changes where two floor types meet, in profiles matched to each height change. They cover the expansion gap and protect exposed plank edges from chipping under foot traffic.', 'Components', NULL),
  ('trim-pieces', 'material', NULL, 'Tile Edge Trim', 'Metal and PVC tile edge trim that finishes exposed tile edges and transitions to other flooring. Trim protects cut edges from chipping and gives outside corners a clean line.', 'Components', NULL),
  ('tub-drain', 'material', NULL, 'Tub Drain', 'Waste and overflow assembly that connects a bathtub drain and overflow opening to the trap. Combines the drain shoe, overflow elbow, and stopper, with finish trim offered in styles that match faucets.', 'Components', NULL),
  ('underlayment-roll', 'material', NULL, 'Underlayment', 'Foam underlayment roll that cushions floating hardwood, laminate, and LVP over plywood or concrete subfloors. It smooths minor subfloor flaws and dampens the hollow sound of footsteps on a floating floor.', 'Components', NULL),
  ('wall-plate', 'material', NULL, 'Wall Plate', 'Replacement cover plates for outlets and switches after device swaps.', 'Components', NULL),
  ('waterproof-cement-board', 'material', NULL, 'Waterproof Cement Board', 'Cement backer board with a factory waterproof coating for tiled shower walls, tub surrounds, and wet floors. Gives a rigid, mold-resistant tile base that only needs its seams and fasteners sealed to finish the waterproof layer.', 'Components', NULL),
  ('waterproof-foam-board', 'material', NULL, 'Waterproof Foam Board', 'Lightweight extruded foam backer board with a factory waterproof facing, sized in sheets for shower walls, benches, and niches. Stays dimensionally stable and blocks water once its seams and fastener heads are sealed.', 'Components', NULL),
  ('wedge-spacer', 'material', NULL, 'Wedge Spacer', 'Tapered plastic wedges that support the first course of wall tile and fine-tune joint width before thinset grabs. The taper adjusts gaps in small increments that fixed spacers cannot.', 'Consumables', NULL),
  ('window-unit', 'material', NULL, 'Window Unit', 'Replacement or new-construction window unit matched to the rough opening.', 'Components', NULL),
  ('wire-nut', 'material', NULL, 'Wire Nut', 'Twist-on wire connectors for joining conductors in outlet and switch boxes.', 'Components', NULL),
  ('wire-pigtail', 'material', NULL, 'Wire Pigtail', 'Pre-cut solid copper pigtails for extending short box wires to new devices. 12 in length.', 'Components', NULL),
  ('wood-fence-pickets', 'material', NULL, 'Wood Fence Pickets', 'Individual wood pickets for a classic slat privacy or semi-privacy look.', 'Components', NULL),
  ('wood-finish', 'material', NULL, 'Wood Finish', 'Clear polyurethane or wiping varnish that seals interior furniture. The cured film protects wood from moisture, stains, and wear while showing the grain.', 'Consumables', NULL),
  ('wood-stain', 'material', NULL, 'Wood Stain', 'Oil or water-based stain for coloring bare wood before topcoats.', 'Consumables', NULL),
  ('tongue-and-groove-pliers', 'tool', NULL, 'Tongue-and-Groove Pliers', NULL, 'Hand Tool', 1);
INSERT INTO _vm_redirect VALUES
  ('e32147af-e081-4884-8ddf-c6d4dde724ac'::uuid, 'tool', 'framing-nailer'),
  ('d19076c5-9870-4ee1-8daf-f32f46ddc103'::uuid, 'tool', 'level'),
  ('d3b50e21-61fc-4a87-9a2f-7ae6ea4ef007'::uuid, 'material', 'nitrile-gloves'),
  ('53809ee6-a851-427a-84c2-cda072126a61'::uuid, 'tool', 'notched-trowel'),
  ('38990faa-9442-471e-9c76-1ebb94a484cb'::uuid, 'tool', 'oscillating-multi-tool'),
