-- Project Partner and Toolio vocabulary link, phase 3 (one migration).
-- Generated by scripts/vocab-merge/build-pp-load.mjs from the reviewed crosswalk; do not edit by hand.
-- Export folder: 2026-11-02-p3
-- Expected after load: 310 tools, 171 materials, 31 categories, 55 project families.
-- Apply in one run. Any failed check rolls everything back.

BEGIN;

-- ===========================================================================
-- Part 1: vocabulary schema (expand). Old structures stay in place.
-- ===========================================================================

CREATE TABLE IF NOT EXISTS public.vocab_keys (
  public_key text PRIMARY KEY CHECK (public_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  entity text NOT NULL CHECK (entity IN ('category', 'project', 'tool', 'material')),
  created_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz,
  replaced_by_public_key text REFERENCES public.vocab_keys (public_key),
  CHECK (replaced_by_public_key IS NULL OR removed_at IS NOT NULL)
);

ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS public_key text REFERENCES public.vocab_keys (public_key);
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS name_key text;
ALTER TABLE public.materials ADD COLUMN IF NOT EXISTS public_key text REFERENCES public.vocab_keys (public_key);
ALTER TABLE public.materials ADD COLUMN IF NOT EXISTS name_key text;
ALTER TABLE public.projects ADD COLUMN IF NOT EXISTS public_key text REFERENCES public.vocab_keys (public_key);

ALTER TABLE public.projects DROP CONSTRAINT IF EXISTS projects_public_key_root_only;
ALTER TABLE public.projects
  ADD CONSTRAINT projects_public_key_root_only CHECK (public_key IS NULL OR parent_project_id IS NULL);

CREATE TABLE IF NOT EXISTS public.project_categories (
  public_key text PRIMARY KEY REFERENCES public.vocab_keys (public_key),
  name text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.vocab_aliases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  public_key text NOT NULL REFERENCES public.vocab_keys (public_key),
  alias text NOT NULL,
  source text NOT NULL CHECK (source IN ('pp_name', 'pp_revision_name', 'toolio_name', 'alternates', 'merged_term')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (public_key, alias)
);

CREATE TABLE IF NOT EXISTS public.project_family_tools (
  family_key text NOT NULL REFERENCES public.vocab_keys (public_key),
  term_key text NOT NULL REFERENCES public.vocab_keys (public_key),
  role text NOT NULL CHECK (role IN ('required', 'substitute')),
  source text NOT NULL CHECK (source IN ('steps', 'toolio_seed')),
  PRIMARY KEY (family_key, term_key, source)
);

CREATE TABLE IF NOT EXISTS public.vocab_removal_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  public_key text NOT NULL REFERENCES public.vocab_keys (public_key),
  requested_by_app text NOT NULL CHECK (requested_by_app IN ('pp', 'toolio')),
  requested_by_email text NOT NULL,
  reason text,
  replacement_key text REFERENCES public.vocab_keys (public_key),
  pp_decision text CHECK (pp_decision IN ('approve', 'reject')),
  pp_decided_by text,
  pp_decided_at timestamptz,
  toolio_decision text CHECK (toolio_decision IN ('approve', 'reject')),
  toolio_decided_by text,
  toolio_decided_at timestamptz,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'approved', 'rejected', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (replacement_key IS NULL OR replacement_key <> public_key)
);
CREATE UNIQUE INDEX IF NOT EXISTS vocab_removal_requests_one_open
  ON public.vocab_removal_requests (public_key) WHERE status = 'open';

CREATE TABLE IF NOT EXISTS public.vocab_change_events (
  seq bigserial PRIMARY KEY,
  entity text NOT NULL,
  public_key text NOT NULL,
  change_kind text NOT NULL CHECK (change_kind IN ('upsert', 'remove', 'removal_request')),
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS vocab_change_events_created_at ON public.vocab_change_events (created_at);

-- Row level security: vocabulary is readable by signed-in users, written by admins.
-- Removal requests are admin-only and change only through the vocab_* functions.
-- The change feed has no client access (service role only).
ALTER TABLE public.vocab_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vocab_aliases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_family_tools ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vocab_removal_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vocab_change_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS vocab_keys_select ON public.vocab_keys;
CREATE POLICY vocab_keys_select ON public.vocab_keys FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS project_categories_select ON public.project_categories;
CREATE POLICY project_categories_select ON public.project_categories FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS project_categories_insert ON public.project_categories;
CREATE POLICY project_categories_insert ON public.project_categories FOR INSERT TO authenticated WITH CHECK (public.is_admin());
DROP POLICY IF EXISTS project_categories_update ON public.project_categories;
CREATE POLICY project_categories_update ON public.project_categories FOR UPDATE TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS vocab_aliases_select ON public.vocab_aliases;
CREATE POLICY vocab_aliases_select ON public.vocab_aliases FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS vocab_aliases_insert ON public.vocab_aliases;
CREATE POLICY vocab_aliases_insert ON public.vocab_aliases FOR INSERT TO authenticated WITH CHECK (public.is_admin());
DROP POLICY IF EXISTS vocab_aliases_delete ON public.vocab_aliases;
CREATE POLICY vocab_aliases_delete ON public.vocab_aliases FOR DELETE TO authenticated USING (public.is_admin());

DROP POLICY IF EXISTS project_family_tools_select ON public.project_family_tools;
CREATE POLICY project_family_tools_select ON public.project_family_tools FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS vocab_removal_requests_select ON public.vocab_removal_requests;
CREATE POLICY vocab_removal_requests_select ON public.vocab_removal_requests FOR SELECT TO authenticated USING (public.is_admin());

-- Toolio inventory_item_name_comparison_key, copied verbatim under a Project Partner name.
CREATE OR REPLACE FUNCTION public.vocab_name_key(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT lower(trim(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g')));
$function$;

-- ===========================================================================
-- Part 2: vocabulary functions. public.vocab_name_key is created just before
-- this part from Toolio's inventory_item_name_comparison_key definition.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.vocab_kebab(p_text text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT trim(both '-' FROM regexp_replace(lower(p_text), '[^a-z0-9]+', '-', 'g'))
$$;

-- Registers a key for a new Project Partner term, derived from its name.
CREATE OR REPLACE FUNCTION public.vocab_new_key(p_entity text, p_name text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key text := public.vocab_kebab(p_name);
BEGIN
  IF v_key IS NULL OR v_key = '' THEN
    RAISE EXCEPTION 'Cannot derive a key from the name "%"', p_name;
  END IF;
  IF EXISTS (SELECT 1 FROM public.vocab_keys WHERE public_key = v_key) THEN
    RAISE EXCEPTION 'The key "%" is already used by another category, project, tool, or material. Choose a different name.', v_key;
  END IF;
  RETURN v_key;
END;
$$;

-- Converts tool/material entries to the step-entry shape with a library_id.
-- p_map: {"by_id": {"<library id>": {"id","name","category"}}, "by_name": {"<kind>|<name>": {...}}}
-- Library selections ({item, coreItemId}) resolve by coreItemId, step entries by library_id, then by name.
-- With p_require_all, an entry that resolves to nothing raises; otherwise it is left unchanged.
CREATE OR REPLACE FUNCTION public.vocab_map_entries(p_entries jsonb, p_kind text, p_map jsonb, p_require_all boolean)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_out jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_src_id text;
  v_src_name text;
  v_target jsonb;
  v_base jsonb;
BEGIN
  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' THEN
    RETURN p_entries;
  END IF;
  FOR v_entry IN SELECT e.value FROM jsonb_array_elements(p_entries) WITH ORDINALITY AS e(value, n) ORDER BY e.n LOOP
    IF jsonb_typeof(v_entry) <> 'object' THEN
      IF p_require_all THEN
        RAISE EXCEPTION 'vocab: % entry is not an object: %', p_kind, v_entry;
      END IF;
      v_out := v_out || jsonb_build_array(v_entry);
      CONTINUE;
    END IF;
    IF v_entry ? 'coreItemId' THEN
      v_src_id := v_entry->>'coreItemId';
      v_src_name := v_entry->>'item';
    ELSE
      v_src_id := v_entry->>'library_id';
      v_src_name := v_entry->>'name';
    END IF;
    v_target := NULL;
    IF v_src_id IS NOT NULL AND (p_map->'by_id') ? v_src_id THEN
      v_target := p_map->'by_id'->v_src_id;
    ELSIF v_src_name IS NOT NULL AND (p_map->'by_name') ? (p_kind || '|' || v_src_name) THEN
      v_target := p_map->'by_name'->(p_kind || '|' || v_src_name);
    END IF;
    IF v_target IS NULL THEN
      IF p_require_all THEN
        RAISE EXCEPTION 'vocab: unresolved % entry %', p_kind, v_entry;
      END IF;
      v_out := v_out || jsonb_build_array(v_entry);
      CONTINUE;
    END IF;
    v_base := v_entry - 'item' - 'coreItemId' - 'isPrime' - 'attributes' - 'variationId' - 'library_tool_id' - 'library_material_id';
    IF NOT v_base ? 'id' THEN
      v_base := v_base || jsonb_build_object('id', p_kind || '-' || gen_random_uuid());
    END IF;
    IF NOT v_base ? 'alternates' THEN
      v_base := v_base || jsonb_build_object('alternates', '[]'::jsonb);
    END IF;
    IF NOT v_base ? 'category' AND v_target ? 'category' THEN
      v_base := v_base || jsonb_build_object('category', v_target->'category');
    END IF;
    IF NOT v_base ? 'legacy_name' THEN
      v_base := v_base || jsonb_build_object('legacy_name', v_src_name);
    END IF;
    v_base := v_base || jsonb_build_object('name', v_target->'name', 'library_id', v_target->'id');
    v_out := v_out || jsonb_build_array(v_base);
  END LOOP;
  RETURN v_out;
END;
$$;

-- Applies vocab_map_entries to every step's tools and materials inside a phases array.
CREATE OR REPLACE FUNCTION public.vocab_walk_phases(p_phases jsonb, p_map jsonb, p_require_all boolean)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_out jsonb := '[]'::jsonb;
  v_phase jsonb;
  v_ops jsonb;
  v_op jsonb;
  v_steps jsonb;
  v_step jsonb;
BEGIN
  IF p_phases IS NULL OR jsonb_typeof(p_phases) <> 'array' THEN
    RETURN p_phases;
  END IF;
  FOR v_phase IN SELECT p.value FROM jsonb_array_elements(p_phases) WITH ORDINALITY AS p(value, n) ORDER BY p.n LOOP
    IF jsonb_typeof(v_phase) = 'object' AND jsonb_typeof(v_phase->'operations') = 'array' THEN
      v_ops := '[]'::jsonb;
      FOR v_op IN SELECT o.value FROM jsonb_array_elements(v_phase->'operations') WITH ORDINALITY AS o(value, n) ORDER BY o.n LOOP
        IF jsonb_typeof(v_op) = 'object' AND jsonb_typeof(v_op->'steps') = 'array' THEN
          v_steps := '[]'::jsonb;
          FOR v_step IN SELECT s.value FROM jsonb_array_elements(v_op->'steps') WITH ORDINALITY AS s(value, n) ORDER BY s.n LOOP
            IF jsonb_typeof(v_step) = 'object' THEN
              IF jsonb_typeof(v_step->'tools') = 'array' THEN
                v_step := jsonb_set(v_step, '{tools}', public.vocab_map_entries(v_step->'tools', 'tool', p_map, p_require_all));
              END IF;
              IF jsonb_typeof(v_step->'materials') = 'array' THEN
                v_step := jsonb_set(v_step, '{materials}', public.vocab_map_entries(v_step->'materials', 'material', p_map, p_require_all));
              END IF;
            END IF;
            v_steps := v_steps || jsonb_build_array(v_step);
          END LOOP;
          v_op := jsonb_set(v_op, '{steps}', v_steps);
        END IF;
        v_ops := v_ops || jsonb_build_array(v_op);
      END LOOP;
      v_phase := jsonb_set(v_phase, '{operations}', v_ops);
    END IF;
    v_out := v_out || jsonb_build_array(v_phase);
  END LOOP;
  RETURN v_out;
END;
$$;

-- project_runs.phases may hold a JSON string that contains the phases; it is walked and stored back the same way.
CREATE OR REPLACE FUNCTION public.vocab_walk_run_phases(p_phases jsonb, p_map jsonb, p_require_all boolean)
RETURNS jsonb
LANGUAGE sql
AS $$
  SELECT CASE jsonb_typeof(p_phases)
    WHEN 'string' THEN to_jsonb(public.vocab_walk_phases((p_phases #>> '{}')::jsonb, p_map, p_require_all)::text)
    ELSE public.vocab_walk_phases(p_phases, p_map, p_require_all)
  END
$$;

-- user_profiles.owned_tools entries {id, tool_id, name, item}: resolves tool_id by id, then by name (name, else item, as the app reads it).
CREATE OR REPLACE FUNCTION public.vocab_map_owned_tools(p_owned jsonb, p_map jsonb, p_require_all boolean)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_out jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_name text;
  v_target jsonb;
BEGIN
  IF p_owned IS NULL OR jsonb_typeof(p_owned) <> 'array' THEN
    RETURN p_owned;
  END IF;
  FOR v_entry IN SELECT e.value FROM jsonb_array_elements(p_owned) WITH ORDINALITY AS e(value, n) ORDER BY e.n LOOP
    v_target := NULL;
    IF jsonb_typeof(v_entry) = 'object' THEN
      v_name := CASE WHEN nullif(btrim(v_entry->>'name'), '') IS NOT NULL THEN v_entry->>'name' ELSE v_entry->>'item' END;
      IF v_entry->>'tool_id' IS NOT NULL AND (p_map->'by_id') ? (v_entry->>'tool_id') THEN
        v_target := p_map->'by_id'->(v_entry->>'tool_id');
      ELSIF v_name IS NOT NULL AND (p_map->'by_name') ? ('tool|' || v_name) THEN
        v_target := p_map->'by_name'->('tool|' || v_name);
      END IF;
    END IF;
    IF v_target IS NULL THEN
      IF p_require_all AND jsonb_typeof(v_entry) = 'object' AND (v_entry->>'tool_id' IS NOT NULL OR v_name IS NOT NULL) THEN
        RAISE EXCEPTION 'vocab: unresolved owned tool %', v_entry;
      END IF;
      v_out := v_out || jsonb_build_array(v_entry);
    ELSE
      v_out := v_out || jsonb_build_array(v_entry || jsonb_build_object('tool_id', v_target->'id'));
    END IF;
  END LOOP;
  RETURN v_out;
END;
$$;

-- A family's current revision: latest published, else newest draft, else none.
CREATE OR REPLACE FUNCTION public.vocab_family_current(p_root uuid)
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id uuid := public.latest_published_in_family(p_root);
BEGIN
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;
  SELECT p.id INTO v_id
  FROM public.projects p
  WHERE (p.id = p_root OR p.parent_project_id = p_root) AND p.publish_status = 'draft'
  ORDER BY p.updated_at DESC
  LIMIT 1;
  RETURN v_id;
END;
$$;

-- Full current state of one term, as carried by the change feed and the snapshot.
CREATE OR REPLACE FUNCTION public.vocab_term_payload(p_key text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key public.vocab_keys%ROWTYPE;
  v_body jsonb;
  v_root public.projects%ROWTYPE;
  v_current public.projects%ROWTYPE;
  v_current_id uuid;
BEGIN
  SELECT * INTO v_key FROM public.vocab_keys WHERE public_key = p_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'vocab: unknown key %', p_key;
  END IF;
  IF v_key.removed_at IS NOT NULL THEN
    RETURN jsonb_build_object('public_key', v_key.public_key, 'entity', v_key.entity, 'removed_at', v_key.removed_at,
      'replaced_by_public_key', v_key.replaced_by_public_key);
  END IF;
  IF v_key.entity = 'tool' THEN
    SELECT jsonb_build_object('id', t.id, 'name', t.name, 'category', t.category, 'description', t.description)
      INTO v_body FROM public.tools t WHERE t.public_key = p_key;
  ELSIF v_key.entity = 'material' THEN
    SELECT jsonb_build_object('id', m.id, 'name', m.name, 'category', m.category, 'description', m.description)
      INTO v_body FROM public.materials m WHERE m.public_key = p_key;
  ELSIF v_key.entity = 'category' THEN
    SELECT jsonb_build_object('name', c.name) INTO v_body FROM public.project_categories c WHERE c.public_key = p_key;
  ELSE
    SELECT * INTO v_root FROM public.projects WHERE public_key = p_key;
    v_current_id := public.vocab_family_current(v_root.id);
    IF v_current_id IS NULL THEN
      v_current := v_root;
    ELSE
      SELECT * INTO v_current FROM public.projects WHERE id = v_current_id;
    END IF;
    v_body := jsonb_build_object(
      'id', v_root.id,
      'current_revision_id', v_current_id,
      'name', v_current.name,
      'description', v_current.description,
      'categories', to_jsonb(v_current.category),
      'tags', to_jsonb(v_current.tags),
      'publish_status', v_current.publish_status,
      'visibility_status', v_current.visibility_status,
      'tools', (SELECT jsonb_agg(jsonb_build_object('term_key', f.term_key, 'role', f.role, 'source', f.source) ORDER BY f.term_key)
                FROM public.project_family_tools f WHERE f.family_key = p_key)
    );
  END IF;
  IF v_body IS NULL THEN
    RAISE EXCEPTION 'vocab: key % has no % row', p_key, v_key.entity;
  END IF;
  RETURN v_body || jsonb_build_object(
    'public_key', p_key,
    'entity', v_key.entity,
    'aliases', (SELECT jsonb_agg(jsonb_build_object('alias', a.alias, 'source', a.source) ORDER BY a.alias)
                FROM public.vocab_aliases a WHERE a.public_key = p_key)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_emit(p_key text, p_kind text)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT k.entity, k.public_key, p_kind, public.vocab_term_payload(k.public_key)
  FROM public.vocab_keys k
  WHERE k.public_key = p_key
$$;

-- Rebuilds a family's tool list from its latest published revision's steps.
CREATE OR REPLACE FUNCTION public.vocab_rebuild_family_tools(p_root uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key text;
  v_rev uuid;
BEGIN
  SELECT public_key INTO v_key FROM public.projects WHERE id = p_root;
  v_rev := public.latest_published_in_family(p_root);
  IF v_key IS NULL OR v_rev IS NULL THEN
    RETURN;
  END IF;
  DELETE FROM public.project_family_tools WHERE family_key = v_key AND source = 'steps';
  SELECT v_key, x.term_key, CASE WHEN bool_or(NOT x.is_substitute) THEN 'required' ELSE 'substitute' END, 'steps'
  FROM (
    SELECT k.public_key AS term_key, (e.value ? 'parentId') AS is_substitute
    FROM public.project_phases ph
    JOIN public.phase_operations op
      ON op.phase_id = CASE WHEN ph.source_phase_id IS NULL THEN ph.id ELSE ph.source_phase_id END
    JOIN public.operation_steps s ON s.operation_id = op.id
    CROSS JOIN LATERAL jsonb_array_elements(
      (CASE WHEN jsonb_typeof(s.tools) = 'array' THEN s.tools ELSE '[]'::jsonb END)
      || (CASE WHEN jsonb_typeof(s.materials) = 'array' THEN s.materials ELSE '[]'::jsonb END)
    ) AS e(value)
    JOIN (SELECT id, public_key FROM public.tools UNION ALL SELECT id, public_key FROM public.materials) k
      ON k.id::text = e.value->>'library_id'
    WHERE ph.project_id = v_rev
  ) x
  GROUP BY x.term_key;
  PERFORM public.vocab_emit(v_key, 'upsert');
END;
$$;

-- ---------------------------------------------------------------------------
-- Two-sided removal
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.vocab_assert_caller(p_app text)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_app = 'pp' THEN
    IF NOT public.is_admin() THEN
      RAISE EXCEPTION 'Only Project Partner admins can act on removal requests';
    END IF;
  ELSIF p_app = 'toolio' THEN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION 'Toolio removal actions come only through the project-partner-vocab function';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unknown app %', p_app;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_emit_request(p_request public.vocab_removal_requests)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT k.entity, k.public_key, 'removal_request', to_jsonb(p_request)
  FROM public.vocab_keys k WHERE k.public_key = p_request.public_key
$$;

CREATE OR REPLACE FUNCTION public.vocab_request_removal(
  p_key text, p_reason text, p_replacement_key text, p_app text, p_email text
)
RETURNS public.vocab_removal_requests
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key public.vocab_keys%ROWTYPE;
  v_replacement public.vocab_keys%ROWTYPE;
  v_request public.vocab_removal_requests%ROWTYPE;
BEGIN
  PERFORM public.vocab_assert_caller(p_app);
  IF p_email IS NULL OR btrim(p_email) = '' THEN
    RAISE EXCEPTION 'A requester email is required';
  END IF;
  SELECT * INTO v_key FROM public.vocab_keys WHERE public_key = p_key;
  IF NOT FOUND OR v_key.removed_at IS NOT NULL THEN
    RAISE EXCEPTION 'No current term with key %', p_key;
  END IF;
  IF p_replacement_key IS NOT NULL THEN
    SELECT * INTO v_replacement FROM public.vocab_keys WHERE public_key = p_replacement_key;
    IF NOT FOUND OR v_replacement.removed_at IS NOT NULL THEN
      RAISE EXCEPTION 'No current term with key %', p_replacement_key;
    END IF;
    IF v_replacement.entity <> v_key.entity THEN
      RAISE EXCEPTION 'The replacement must also be a %', v_key.entity;
    END IF;
  END IF;
    public_key, requested_by_app, requested_by_email, reason, replacement_key,
    pp_decision, pp_decided_by, pp_decided_at, toolio_decision, toolio_decided_by, toolio_decided_at
  ) VALUES (
    p_key, p_app, p_email, p_reason, p_replacement_key,
    CASE WHEN p_app = 'pp' THEN 'approve' END, CASE WHEN p_app = 'pp' THEN p_email END, CASE WHEN p_app = 'pp' THEN now() END,
    CASE WHEN p_app = 'toolio' THEN 'approve' END, CASE WHEN p_app = 'toolio' THEN p_email END, CASE WHEN p_app = 'toolio' THEN now() END
  )
  RETURNING * INTO v_request;
  PERFORM public.vocab_emit_request(v_request);
  IF p_app = 'toolio' THEN
    PERFORM public.notifications_notify_admins(
      'vocab_removal_request',
      'Toolio asks to remove a shared term',
      format('Toolio no longer uses "%s" (%s). Approve or reject the removal in Tools & Materials.', p_key, v_key.entity),
      jsonb_build_object('request_id', v_request.id, 'public_key', p_key)
    );
  END IF;
  RETURN v_request;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_cancel_removal(p_request_id uuid, p_app text, p_email text)
RETURNS public.vocab_removal_requests
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_request public.vocab_removal_requests%ROWTYPE;
BEGIN
  PERFORM public.vocab_assert_caller(p_app);
  SELECT * INTO v_request FROM public.vocab_removal_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.status <> 'open' THEN
    RAISE EXCEPTION 'Removal request % is not open', p_request_id;
  END IF;
  IF v_request.requested_by_app <> p_app THEN
    RAISE EXCEPTION 'Only the app that asked for the removal can cancel it';
  END IF;
  UPDATE public.vocab_removal_requests SET status = 'cancelled', updated_at = now()
  WHERE id = p_request_id RETURNING * INTO v_request;
  PERFORM public.vocab_emit_request(v_request);
  RETURN v_request;
END;
$$;

-- Performs an approved removal. Internal: called only by vocab_decide_removal.
CREATE OR REPLACE FUNCTION public.vocab_complete_removal(p_request_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_request public.vocab_removal_requests%ROWTYPE;
  v_entity text;
  v_old_id uuid;
  v_old_name text;
  v_new_id uuid;
  v_new_name text;
  v_new_category text;
  v_map jsonb;
  v_like text;
  v_step_refs bigint;
  v_copy_refs bigint;
  v_user_refs bigint;
  v_family_ids uuid[];
  v_new_root uuid;
BEGIN
  SELECT * INTO v_request FROM public.vocab_removal_requests WHERE id = p_request_id;
  IF v_request.status <> 'approved' THEN
    RAISE EXCEPTION 'Removal request % is not approved', p_request_id;
  END IF;
  SELECT entity INTO v_entity FROM public.vocab_keys WHERE public_key = v_request.public_key;
  PERFORM set_config('vocab.completing_removal', 'on', true);

  IF v_entity IN ('tool', 'material') THEN
    IF v_entity = 'tool' THEN
      SELECT id, name INTO v_old_id, v_old_name FROM public.tools WHERE public_key = v_request.public_key;
      SELECT id, name, category INTO v_new_id, v_new_name, v_new_category FROM public.tools WHERE public_key = v_request.replacement_key;
    ELSE
      SELECT id, name INTO v_old_id, v_old_name FROM public.materials WHERE public_key = v_request.public_key;
      SELECT id, name, category INTO v_new_id, v_new_name, v_new_category FROM public.materials WHERE public_key = v_request.replacement_key;
    END IF;
    v_like := '%' || v_old_id::text || '%';
    SELECT count(*) INTO v_step_refs FROM public.operation_steps
      WHERE tools::text LIKE v_like OR materials::text LIKE v_like;
    SELECT (SELECT count(*) FROM public.projects WHERE phases::text LIKE v_like)
         + (SELECT count(*) FROM public.project_runs WHERE phases::text LIKE v_like)
      INTO v_copy_refs;
    SELECT (SELECT count(*) FROM public.user_tools WHERE tool_id = v_old_id)
         + (SELECT count(*) FROM public.user_materials WHERE material_id = v_old_id)
         + (SELECT count(*) FROM public.user_profiles WHERE owned_tools::text LIKE v_like)
      INTO v_user_refs;
    IF v_request.replacement_key IS NULL AND v_step_refs + v_copy_refs + v_user_refs > 0 THEN
      RAISE EXCEPTION 'Cannot remove "%": used by % steps, % saved project copies or runs, and % user tool records. Choose a replacement.',
        v_old_name, v_step_refs, v_copy_refs, v_user_refs;
    END IF;
    IF v_request.replacement_key IS NOT NULL THEN
      v_map := jsonb_build_object('by_id', jsonb_build_object(v_old_id::text,
        jsonb_build_object('id', v_new_id, 'name', v_new_name, 'category', v_new_category)), 'by_name', '{}'::jsonb);
      UPDATE public.operation_steps
        SET tools = public.vocab_map_entries(tools, 'tool', v_map, false),
            materials = public.vocab_map_entries(materials, 'material', v_map, false)
        WHERE tools::text LIKE v_like OR materials::text LIKE v_like;
      UPDATE public.projects SET phases = public.vocab_walk_phases(phases, v_map, false) WHERE phases::text LIKE v_like;
      UPDATE public.project_runs SET phases = public.vocab_walk_run_phases(phases, v_map, false) WHERE phases::text LIKE v_like;
      UPDATE public.user_profiles SET owned_tools = public.vocab_map_owned_tools(owned_tools, v_map, false) WHERE owned_tools::text LIKE v_like;
      IF v_entity = 'tool' THEN
        UPDATE public.user_tools SET tool_id = v_new_id WHERE tool_id = v_old_id;
        UPDATE public.tool_variations SET core_item_id = v_new_id WHERE core_item_id = v_old_id;
      ELSE
        UPDATE public.user_materials SET material_id = v_new_id WHERE material_id = v_old_id;
        UPDATE public.materials_variants SET material_id = v_new_id WHERE material_id = v_old_id;
      END IF;
    ELSE
      IF v_entity = 'tool' THEN
        DELETE FROM public.tool_variations WHERE core_item_id = v_old_id;
      ELSE
        DELETE FROM public.materials_variants WHERE material_id = v_old_id;
      END IF;
    END IF;
    IF v_entity = 'tool' THEN
      DELETE FROM public.tools WHERE id = v_old_id;
    ELSE
      DELETE FROM public.materials WHERE id = v_old_id;
    END IF;

  ELSIF v_entity = 'project' THEN
    SELECT array_agg(p.id) INTO v_family_ids
    FROM public.projects p
    WHERE p.id = (SELECT id FROM public.projects WHERE public_key = v_request.public_key)
       OR p.parent_project_id = (SELECT id FROM public.projects WHERE public_key = v_request.public_key);
    SELECT id INTO v_new_root FROM public.projects WHERE public_key = v_request.replacement_key;
    UPDATE public.project_runs SET project_id = v_new_root WHERE project_id = ANY (v_family_ids);
    DELETE FROM public.operation_steps WHERE operation_id IN (
      SELECT op.id FROM public.phase_operations op
      JOIN public.project_phases ph ON op.phase_id = ph.id
      WHERE ph.project_id = ANY (v_family_ids));
    DELETE FROM public.phase_operations WHERE phase_id IN (SELECT id FROM public.project_phases WHERE project_id = ANY (v_family_ids));
    DELETE FROM public.project_phases WHERE project_id = ANY (v_family_ids);
    DELETE FROM public.projects WHERE id = ANY (v_family_ids) AND parent_project_id IS NOT NULL;
    DELETE FROM public.projects WHERE id = ANY (v_family_ids);

  ELSE
    SELECT name INTO v_old_name FROM public.project_categories WHERE public_key = v_request.public_key;
    SELECT name INTO v_new_name FROM public.project_categories WHERE public_key = v_request.replacement_key;
    UPDATE public.projects
      SET category = (
        SELECT array_agg(DISTINCT c ORDER BY c)
        FROM unnest(array_remove(category, v_old_name) || CASE WHEN v_new_name IS NULL THEN ARRAY[]::text[] ELSE ARRAY[v_new_name] END) AS c
      )
      WHERE v_old_name = ANY (category);
    DELETE FROM public.project_categories WHERE public_key = v_request.public_key;
  END IF;

  IF v_request.replacement_key IS NOT NULL THEN
      SELECT family_key, v_request.replacement_key, role, source FROM public.project_family_tools WHERE term_key = v_request.public_key
      ON CONFLICT DO NOTHING;
      SELECT v_request.replacement_key, alias, source FROM public.vocab_aliases WHERE public_key = v_request.public_key
      ON CONFLICT DO NOTHING;
    IF v_old_name IS NOT NULL THEN
        ON CONFLICT DO NOTHING;
    END IF;
  END IF;
  DELETE FROM public.project_family_tools WHERE term_key = v_request.public_key OR family_key = v_request.public_key;
  DELETE FROM public.vocab_aliases WHERE public_key = v_request.public_key;
  UPDATE public.vocab_keys SET removed_at = now(), replaced_by_public_key = v_request.replacement_key
    WHERE public_key = v_request.public_key;
  PERFORM public.vocab_emit(v_request.public_key, 'remove');
  IF v_request.replacement_key IS NOT NULL THEN
    PERFORM public.vocab_emit(v_request.replacement_key, 'upsert');
  END IF;
  PERFORM set_config('vocab.completing_removal', 'off', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_decide_removal(p_request_id uuid, p_app text, p_decision text, p_email text)
RETURNS public.vocab_removal_requests
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_request public.vocab_removal_requests%ROWTYPE;
BEGIN
  PERFORM public.vocab_assert_caller(p_app);
  IF p_decision NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Decision must be approve or reject';
  END IF;
  SELECT * INTO v_request FROM public.vocab_removal_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.status <> 'open' THEN
    RAISE EXCEPTION 'Removal request % is not open', p_request_id;
  END IF;
  IF v_request.requested_by_app = p_app THEN
    RAISE EXCEPTION 'The other app decides this request';
  END IF;
  IF p_app = 'pp' THEN
    UPDATE public.vocab_removal_requests
      SET pp_decision = p_decision, pp_decided_by = p_email, pp_decided_at = now(),
          status = CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, updated_at = now()
      WHERE id = p_request_id RETURNING * INTO v_request;
  ELSE
    UPDATE public.vocab_removal_requests
      SET toolio_decision = p_decision, toolio_decided_by = p_email, toolio_decided_at = now(),
          status = CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, updated_at = now()
      WHERE id = p_request_id RETURNING * INTO v_request;
  END IF;
  PERFORM public.vocab_emit_request(v_request);
  IF v_request.status = 'approved' THEN
    PERFORM public.vocab_complete_removal(p_request_id);
  END IF;
  RETURN v_request;
END;
$$;

-- ---------------------------------------------------------------------------
-- Toolio access (project-partner-vocab edge function, service role only)
-- ---------------------------------------------------------------------------

-- Every current term plus open removal requests, and the feed position they reflect.
CREATE OR REPLACE FUNCTION public.vocab_snapshot()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_seq bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'vocab_snapshot is for the project-partner-vocab function' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT max(seq) INTO v_seq FROM public.vocab_change_events;
  RETURN jsonb_build_object(
    'as_of_seq', CASE WHEN v_seq IS NULL THEN 0 ELSE v_seq END,
    'terms', (SELECT jsonb_agg(public.vocab_term_payload(k.public_key) ORDER BY k.entity, k.public_key)
              FROM public.vocab_keys k WHERE k.removed_at IS NULL),
    'removal_requests', (SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at)
                         FROM public.vocab_removal_requests r WHERE r.status = 'open')
  );
END;
$$;

-- Creates a term under a key Toolio chooses (core sku or project slug). The requester must be a Project Partner admin.
CREATE OR REPLACE FUNCTION public.vocab_create_term(
  p_entity text, p_key text, p_name text, p_description text, p_category text, p_specialty_scale integer, p_email text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'vocab_create_term is for the project-partner-vocab function' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT u.id INTO v_user FROM auth.users u WHERE lower(u.email) = lower(p_email);
  IF v_user IS NULL OR NOT public.is_admin(v_user) THEN
    RAISE EXCEPTION '% is not a Project Partner admin', p_email USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF EXISTS (SELECT 1 FROM public.vocab_keys WHERE public_key = p_key) THEN
    RAISE EXCEPTION 'Key % already exists', p_key USING ERRCODE = 'unique_violation';
  END IF;
  IF p_entity IN ('tool', 'material') AND EXISTS (
    SELECT 1 FROM public.tools WHERE p_entity = 'tool' AND name_key = public.vocab_name_key(p_name)
    UNION ALL SELECT 1 FROM public.materials WHERE p_entity = 'material' AND name_key = public.vocab_name_key(p_name)
  ) THEN
    RAISE EXCEPTION 'A % named % already exists', p_entity, p_name USING ERRCODE = 'unique_violation';
  END IF;
  IF p_entity = 'tool' THEN
      VALUES (p_name, p_description, p_category, p_specialty_scale, p_key);
  ELSIF p_entity = 'material' THEN
  ELSIF p_entity = 'category' THEN
  ELSIF p_entity = 'project' THEN
      VALUES (p_name, p_description, CASE WHEN p_category IS NULL THEN ARRAY[]::text[] ELSE ARRAY[p_category] END,
              'draft', 'coming-soon', p_key);
  ELSE
    RAISE EXCEPTION 'Unknown entity %', p_entity;
  END IF;
  RETURN public.vocab_term_payload(p_key);
END;
$$;

REVOKE ALL ON FUNCTION public.vocab_snapshot() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.vocab_create_term(text, text, text, text, text, integer, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.vocab_snapshot() TO service_role;
GRANT EXECUTE ON FUNCTION public.vocab_create_term(text, text, text, text, text, integer, text) TO service_role;

REVOKE ALL ON FUNCTION public.vocab_complete_removal(uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.vocab_emit(text, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.vocab_emit_request(public.vocab_removal_requests) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.vocab_new_key(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.vocab_request_removal(text, text, text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.vocab_decide_removal(uuid, text, text, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.vocab_cancel_removal(uuid, text, text) TO authenticated, service_role;


-- ===========================================================================
-- Part 3: load (generated by scripts/vocab-merge/build-pp-load.mjs)
-- ===========================================================================

CREATE TEMP TABLE _vm_library (key text PRIMARY KEY, entity text NOT NULL, pp_id uuid, name text NOT NULL,
  description text, category text, specialty_scale integer) ON COMMIT DROP;

CREATE TEMP TABLE _vm_redirect (old_id uuid PRIMARY KEY, old_entity text NOT NULL, target_key text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_id_alias (old_id text PRIMARY KEY, target_key text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_name_map (kind text NOT NULL, name text NOT NULL, target_key text NOT NULL, PRIMARY KEY (kind, name)) ON COMMIT DROP;

CREATE TEMP TABLE _vm_alias (key text NOT NULL, alias text NOT NULL, source text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_category (key text PRIMARY KEY, name text NOT NULL UNIQUE) ON COMMIT DROP;

CREATE TEMP TABLE _vm_category_rename (old_name text PRIMARY KEY, new_name text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_family (key text PRIMARY KEY, pp_root uuid, name text NOT NULL, rename boolean NOT NULL,
  description text, categories text[]) ON COMMIT DROP;

CREATE TEMP TABLE _vm_family_category (key text NOT NULL, category text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_seed_tools (family_key text NOT NULL, term_key text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _vm_parity (name text PRIMARY KEY, name_key text NOT NULL) ON COMMIT DROP;


-- Keys for every term.
  SELECT key, entity FROM _vm_library
  UNION ALL SELECT key, 'category' FROM _vm_category
  UNION ALL SELECT key, 'project' FROM _vm_family;

-- Kept library rows get their key; new terms are inserted.
UPDATE public.tools t SET public_key = l.key FROM _vm_library l WHERE l.pp_id = t.id AND l.entity = 'tool';
UPDATE public.materials m SET public_key = l.key FROM _vm_library l WHERE l.pp_id = m.id AND l.entity = 'material';
  SELECT name, description, category, specialty_scale, key FROM _vm_library WHERE pp_id IS NULL AND entity = 'tool';
  SELECT name, description, category, key FROM _vm_library WHERE pp_id IS NULL AND entity = 'material';

-- Merged-away rows: variations and ownership move to the kept term, then the rows are deleted.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM _vm_redirect r JOIN public.tool_variations v ON v.core_item_id = r.old_id
    WHERE r.old_entity = 'tool' AND NOT EXISTS (SELECT 1 FROM public.tools t WHERE t.public_key = r.target_key)
  ) OR EXISTS (
    SELECT 1 FROM _vm_redirect r JOIN public.materials_variants v ON v.material_id = r.old_id
    WHERE r.old_entity = 'material' AND NOT EXISTS (SELECT 1 FROM public.materials m WHERE m.public_key = r.target_key)
  ) THEN
    RAISE EXCEPTION 'vocab load: a merged-away row with variations would move between tools and materials';
  END IF;
END $$;
UPDATE public.tool_variations v SET core_item_id = t.id
  FROM _vm_redirect r JOIN public.tools t ON t.public_key = r.target_key WHERE v.core_item_id = r.old_id;
UPDATE public.materials_variants v SET material_id = m.id
  FROM _vm_redirect r JOIN public.materials m ON m.public_key = r.target_key WHERE v.material_id = r.old_id;
UPDATE public.user_tools u SET tool_id = t.id
  FROM _vm_redirect r JOIN public.tools t ON t.public_key = r.target_key WHERE u.tool_id = r.old_id;
UPDATE public.user_materials u SET material_id = m.id
  FROM _vm_redirect r JOIN public.materials m ON m.public_key = r.target_key WHERE u.material_id = r.old_id;
  SELECT u.user_id, m.id, u.name, u.quantity, u.description, u.user_photo_url
  FROM public.user_tools u JOIN _vm_redirect r ON r.old_id = u.tool_id JOIN public.materials m ON m.public_key = r.target_key;
DELETE FROM public.user_tools u USING _vm_redirect r, public.materials m WHERE u.tool_id = r.old_id AND m.public_key = r.target_key;
  SELECT u.user_id, t.id, u.name, u.quantity, u.description, u.user_photo_url
  FROM public.user_materials u JOIN _vm_redirect r ON r.old_id = u.material_id JOIN public.tools t ON t.public_key = r.target_key;
DELETE FROM public.user_materials u USING _vm_redirect r, public.tools t WHERE u.material_id = r.old_id AND t.public_key = r.target_key;
DELETE FROM public.tools WHERE id IN (SELECT old_id FROM _vm_redirect WHERE old_entity = 'tool');
DELETE FROM public.materials WHERE id IN (SELECT old_id FROM _vm_redirect WHERE old_entity = 'material');

-- Canonical names and descriptions, then normalized names.
UPDATE public.tools t SET name = l.name, description = CASE WHEN l.description IS NULL THEN t.description ELSE l.description END
  FROM _vm_library l WHERE l.key = t.public_key;
UPDATE public.materials m SET name = l.name, description = CASE WHEN l.description IS NULL THEN m.description ELSE l.description END
  FROM _vm_library l WHERE l.key = m.public_key;
UPDATE public.tools SET name_key = public.vocab_name_key(name);
UPDATE public.materials SET name_key = public.vocab_name_key(name);

-- One map for every step entry and owned tool: library ids (kept rows, merged-away rows, gone rows) and names.
CREATE TEMP TABLE _vm_targets ON COMMIT DROP AS
  SELECT public_key AS key, id, name, category FROM public.tools
  UNION ALL SELECT public_key, id, name, category FROM public.materials;
CREATE TEMP TABLE _vm_map ON COMMIT DROP AS
SELECT jsonb_build_object(
  'by_id', (
    SELECT jsonb_object_agg(src, jsonb_build_object('id', t.id, 'name', t.name, 'category', t.category))
    FROM (
      SELECT id::text AS src, key FROM _vm_targets
      UNION ALL SELECT old_id::text, target_key FROM _vm_redirect
      UNION ALL SELECT old_id, target_key FROM _vm_id_alias
    ) ids JOIN _vm_targets t ON t.key = ids.key
  ),
  'by_name', (
    SELECT jsonb_object_agg(n.kind || '|' || n.name, jsonb_build_object('id', t.id, 'name', t.name, 'category', t.category))
    FROM _vm_name_map n JOIN _vm_targets t ON t.key = n.target_key
  )
) AS m;

UPDATE public.operation_steps
  SET tools = public.vocab_map_entries(tools, 'tool', (SELECT m FROM _vm_map), true)
  WHERE jsonb_typeof(tools) = 'array';
UPDATE public.operation_steps
  SET materials = public.vocab_map_entries(materials, 'material', (SELECT m FROM _vm_map), true)
  WHERE jsonb_typeof(materials) = 'array';
UPDATE public.projects SET phases = public.vocab_walk_run_phases(phases, (SELECT m FROM _vm_map), true) WHERE phases IS NOT NULL;
UPDATE public.project_runs SET phases = public.vocab_walk_run_phases(phases, (SELECT m FROM _vm_map), true) WHERE phases IS NOT NULL;
UPDATE public.user_profiles SET owned_tools = public.vocab_map_owned_tools(owned_tools, (SELECT m FROM _vm_map), true)
  WHERE owned_tools IS NOT NULL;

-- Categories become vocabulary; projects carry the final names.
UPDATE public.projects p
  SET category = (
    SELECT array_agg(DISTINCT CASE WHEN r.old_name IS NULL THEN c ELSE r.new_name END)
    FROM unnest(p.category) AS c LEFT JOIN _vm_category_rename r ON r.old_name = c
  )
  WHERE cardinality(p.category) > 0;

-- Project families: keys and names on existing families, new families as drafts.
UPDATE public.projects p SET public_key = f.key FROM _vm_family f WHERE p.id = f.pp_root;
UPDATE public.projects p SET name = f.name
  FROM _vm_family f WHERE f.rename AND (p.id = f.pp_root OR p.parent_project_id = f.pp_root);
  SELECT name, description, categories, 'draft', 'coming-soon', key FROM _vm_family WHERE pp_root IS NULL;
UPDATE public.projects p
  SET category = (SELECT array_agg(DISTINCT c) FROM unnest(p.category || a.categories) AS c)
  FROM (SELECT key, array_agg(category) AS categories FROM _vm_family_category GROUP BY key) a
  JOIN public.projects root ON root.public_key = a.key
  WHERE p.id = root.id OR p.parent_project_id = root.id;

  SELECT DISTINCT ON (key, alias) key, alias, source FROM _vm_alias ORDER BY key, alias, source
  ON CONFLICT (public_key, alias) DO NOTHING;

  SELECT family_key, term_key, 'required', 'toolio_seed' FROM _vm_seed_tools;
DO $$ BEGIN PERFORM public.vocab_rebuild_family_tools(id) FROM public.projects WHERE public_key IS NOT NULL; END $$;
-- The feed starts after the load: Toolio's first snapshot carries this state.
DELETE FROM public.vocab_change_events;

-- ---------------------------------------------------------------------------
-- Accounting: any failure rolls the whole migration back.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_count bigint;
  v_detail text;
BEGIN
  SELECT count(*) INTO v_count FROM public.tools;
  IF v_count <> 310 THEN RAISE EXCEPTION 'vocab load: % tools, expected 310', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.materials;
  IF v_count <> 171 THEN RAISE EXCEPTION 'vocab load: % materials, expected 171', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.project_categories;
  IF v_count <> 31 THEN RAISE EXCEPTION 'vocab load: % categories, expected 31', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.projects WHERE parent_project_id IS NULL;
  IF v_count <> 55 THEN RAISE EXCEPTION 'vocab load: % project families, expected 55', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.projects WHERE parent_project_id IS NULL AND public_key IS NULL;
  IF v_count > 0 THEN RAISE EXCEPTION 'vocab load: % project families without a key', v_count; END IF;
  SELECT count(*) INTO v_count FROM (SELECT public_key FROM public.tools UNION ALL SELECT public_key FROM public.materials) k WHERE k.public_key IS NULL;
  IF v_count > 0 THEN RAISE EXCEPTION 'vocab load: % library rows without a key', v_count; END IF;

  SELECT string_agg(p.name || ' -> ' || public.vocab_name_key(p.name) || ' (Toolio ' || p.name_key || ')', ', ')
    INTO v_detail FROM _vm_parity p WHERE public.vocab_name_key(p.name) IS DISTINCT FROM p.name_key;
  IF v_detail IS NOT NULL THEN RAISE EXCEPTION 'vocab load: name normalization differs from Toolio: %', v_detail; END IF;

  SELECT count(*) INTO v_count
  FROM public.operation_steps s,
       jsonb_array_elements(
         (CASE WHEN jsonb_typeof(s.tools) = 'array' THEN s.tools ELSE '[]'::jsonb END)
         || (CASE WHEN jsonb_typeof(s.materials) = 'array' THEN s.materials ELSE '[]'::jsonb END)) e
  WHERE NOT EXISTS (SELECT 1 FROM _vm_targets t WHERE t.id::text = e.value->>'library_id');
  IF v_count > 0 THEN RAISE EXCEPTION 'vocab load: % step entries without a valid library_id', v_count; END IF;

  SELECT count(*) INTO v_count
  FROM public.user_profiles u, jsonb_array_elements(CASE WHEN jsonb_typeof(u.owned_tools) = 'array' THEN u.owned_tools ELSE '[]'::jsonb END) e
  WHERE e.value->>'tool_id' IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.tools t WHERE t.id::text = e.value->>'tool_id');
  IF v_count > 0 THEN RAISE EXCEPTION 'vocab load: % owned tools point to no tool', v_count; END IF;

  SELECT string_agg(DISTINCT c, ', ') INTO v_detail
  FROM public.projects p, unnest(p.category) AS c
  WHERE NOT EXISTS (SELECT 1 FROM public.project_categories pc WHERE pc.name = c);
  IF v_detail IS NOT NULL THEN RAISE EXCEPTION 'vocab load: projects use unknown categories: %', v_detail; END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS tools_public_key_unique ON public.tools (public_key);
CREATE UNIQUE INDEX IF NOT EXISTS materials_public_key_unique ON public.materials (public_key);
CREATE UNIQUE INDEX IF NOT EXISTS projects_public_key_unique ON public.projects (public_key);
CREATE UNIQUE INDEX IF NOT EXISTS tools_name_key_unique ON public.tools (name_key);
CREATE UNIQUE INDEX IF NOT EXISTS materials_name_key_unique ON public.materials (name_key);
ALTER TABLE public.tools ALTER COLUMN public_key SET NOT NULL;
ALTER TABLE public.tools ALTER COLUMN name_key SET NOT NULL;
ALTER TABLE public.materials ALTER COLUMN public_key SET NOT NULL;
ALTER TABLE public.materials ALTER COLUMN name_key SET NOT NULL;

-- ===========================================================================
-- Part 4: triggers, created after the load so the load emits no events.
-- ===========================================================================

-- tools / materials: key assignment, immutability, normalized name; TG_ARGV[0] is the entity.
CREATE OR REPLACE FUNCTION public.vocab_library_before_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.public_key IS NOT NULL AND NEW.public_key IS DISTINCT FROM OLD.public_key THEN
    RAISE EXCEPTION 'The key of % "%" cannot change', TG_ARGV[0], OLD.name;
  END IF;
  IF NEW.public_key IS NULL THEN
    NEW.public_key := public.vocab_new_key(TG_ARGV[0], NEW.name);
  END IF;
  NEW.name_key := public.vocab_name_key(NEW.name);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_library_after_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.vocab_emit(NEW.public_key, 'upsert');
  RETURN NULL;
END;
$$;

-- projects: only family roots carry a key; revisions never do. Categories must be vocabulary.
CREATE OR REPLACE FUNCTION public.vocab_projects_before_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_unknown text[];
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.public_key IS NOT NULL AND NEW.parent_project_id IS NOT NULL THEN
    RAISE EXCEPTION 'Project family root "%" cannot become a revision', OLD.name;
  END IF;
  IF NEW.parent_project_id IS NOT NULL THEN
    NEW.public_key := NULL;
  ELSE
    IF TG_OP = 'UPDATE' AND OLD.public_key IS NOT NULL AND NEW.public_key IS DISTINCT FROM OLD.public_key THEN
      RAISE EXCEPTION 'The key of project "%" cannot change', OLD.name;
    END IF;
    IF NEW.public_key IS NULL THEN
      NEW.public_key := public.vocab_new_key('project', NEW.name);
    END IF;
  END IF;
  IF NEW.category IS NOT NULL THEN
    SELECT array_agg(c) INTO v_unknown
    FROM unnest(NEW.category) AS c
    WHERE NOT EXISTS (SELECT 1 FROM public.project_categories pc WHERE pc.name = c);
    IF v_unknown IS NOT NULL THEN
      RAISE EXCEPTION 'Not in the shared category list: %', array_to_string(v_unknown, ', ');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_projects_after_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_root uuid := CASE WHEN NEW.parent_project_id IS NULL THEN NEW.id ELSE NEW.parent_project_id END;
  v_key text;
BEGIN
  SELECT public_key INTO v_key FROM public.projects WHERE id = v_root;
  IF v_key IS NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.publish_status = 'published' AND OLD.publish_status IS DISTINCT FROM 'published' THEN
    PERFORM public.vocab_rebuild_family_tools(v_root);
  ELSE
    PERFORM public.vocab_emit(v_key, 'upsert');
  END IF;
  RETURN NULL;
END;
$$;

-- project_categories: key assignment, immutability, renames carried into projects.category.
CREATE OR REPLACE FUNCTION public.vocab_categories_before_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.public_key IS DISTINCT FROM OLD.public_key THEN
    RAISE EXCEPTION 'The key of category "%" cannot change', OLD.name;
  END IF;
  IF NEW.public_key IS NULL THEN
    NEW.public_key := public.vocab_new_key('category', NEW.name);
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_categories_after_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.name IS DISTINCT FROM OLD.name THEN
    UPDATE public.projects SET category = array_replace(category, OLD.name, NEW.name) WHERE OLD.name = ANY (category);
  END IF;
  PERFORM public.vocab_emit(NEW.public_key, 'upsert');
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.vocab_aliases_after_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- A removal in progress emits its own remove and replacement events.
  IF current_setting('vocab.completing_removal', true) = 'on' THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'DELETE' THEN
    PERFORM public.vocab_emit(OLD.public_key, 'upsert');
  ELSE
    PERFORM public.vocab_emit(NEW.public_key, 'upsert');
  END IF;
  RETURN NULL;
END;
$$;

-- Shared terms are removed only by completing an approved two-sided removal request.
CREATE OR REPLACE FUNCTION public.vocab_delete_guard()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('vocab.completing_removal', true) = 'on' THEN
    RETURN OLD;
  END IF;
  IF OLD.public_key IS NULL THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Shared % "%" cannot be deleted directly. Use Request removal.', TG_ARGV[0], OLD.public_key;
END;
$$;

DROP TRIGGER IF EXISTS vocab_tools_before_write ON public.tools;
CREATE TRIGGER vocab_tools_before_write BEFORE INSERT OR UPDATE ON public.tools
  FOR EACH ROW EXECUTE FUNCTION public.vocab_library_before_write('tool');
DROP TRIGGER IF EXISTS vocab_tools_after_write ON public.tools;
CREATE TRIGGER vocab_tools_after_write AFTER INSERT OR UPDATE OF name, category, description, public_key ON public.tools
  FOR EACH ROW EXECUTE FUNCTION public.vocab_library_after_write();
DROP TRIGGER IF EXISTS vocab_tools_delete_guard ON public.tools;
CREATE TRIGGER vocab_tools_delete_guard BEFORE DELETE ON public.tools
  FOR EACH ROW EXECUTE FUNCTION public.vocab_delete_guard('tool');

DROP TRIGGER IF EXISTS vocab_materials_before_write ON public.materials;
CREATE TRIGGER vocab_materials_before_write BEFORE INSERT OR UPDATE ON public.materials
  FOR EACH ROW EXECUTE FUNCTION public.vocab_library_before_write('material');
DROP TRIGGER IF EXISTS vocab_materials_after_write ON public.materials;
CREATE TRIGGER vocab_materials_after_write AFTER INSERT OR UPDATE OF name, category, description, public_key ON public.materials
  FOR EACH ROW EXECUTE FUNCTION public.vocab_library_after_write();
DROP TRIGGER IF EXISTS vocab_materials_delete_guard ON public.materials;
CREATE TRIGGER vocab_materials_delete_guard BEFORE DELETE ON public.materials
  FOR EACH ROW EXECUTE FUNCTION public.vocab_delete_guard('material');

DROP TRIGGER IF EXISTS vocab_projects_before_write ON public.projects;
CREATE TRIGGER vocab_projects_before_write BEFORE INSERT OR UPDATE ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.vocab_projects_before_write();
DROP TRIGGER IF EXISTS vocab_projects_after_write ON public.projects;
CREATE TRIGGER vocab_projects_after_write
  AFTER INSERT OR UPDATE OF name, description, category, tags, publish_status, visibility_status ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.vocab_projects_after_write();
DROP TRIGGER IF EXISTS vocab_projects_delete_guard ON public.projects;
CREATE TRIGGER vocab_projects_delete_guard BEFORE DELETE ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.vocab_delete_guard('project');

DROP TRIGGER IF EXISTS vocab_categories_before_write ON public.project_categories;
CREATE TRIGGER vocab_categories_before_write BEFORE INSERT OR UPDATE ON public.project_categories
  FOR EACH ROW EXECUTE FUNCTION public.vocab_categories_before_write();
DROP TRIGGER IF EXISTS vocab_categories_after_write ON public.project_categories;
CREATE TRIGGER vocab_categories_after_write AFTER INSERT OR UPDATE ON public.project_categories
  FOR EACH ROW EXECUTE FUNCTION public.vocab_categories_after_write();
DROP TRIGGER IF EXISTS vocab_categories_delete_guard ON public.project_categories;
CREATE TRIGGER vocab_categories_delete_guard BEFORE DELETE ON public.project_categories
  FOR EACH ROW EXECUTE FUNCTION public.vocab_delete_guard('category');

DROP TRIGGER IF EXISTS vocab_aliases_after_write ON public.vocab_aliases;
CREATE TRIGGER vocab_aliases_after_write AFTER INSERT OR UPDATE OR DELETE ON public.vocab_aliases
  FOR EACH ROW EXECUTE FUNCTION public.vocab_aliases_after_write();

COMMIT;
